package com.gielinorbriefing;

import java.util.Arrays;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class FarmPageTest
{
    @Test
    public void groupsPatchRowsIntoSingleCategoryPages()
    {
        List<GielinorDashboardOverlay.FarmPage> pages = GielinorDashboardOverlay.farmPages(
            Arrays.asList(
                "Herb · Ardougne · Torstol · Done",
                "Herb · Catherby · Torstol · Done",
                "Tree · Falador · Yew · Growing",
                "Fruit Tree · Catherby · Palm · Done"),
            15);

        assertEquals(3, pages.size());
        assertEquals("Herbs", pages.get(0).getTitle());
        assertEquals(Arrays.asList(
            "Ardougne · Torstol · Done",
            "Catherby · Torstol · Done"), pages.get(0).getLines());
        assertEquals("Trees", pages.get(1).getTitle());
        assertEquals("Fruit Trees", pages.get(2).getTitle());
    }

    @Test
    public void keepsOverflowPagesWithinTheSameCategory()
    {
        List<GielinorDashboardOverlay.FarmPage> pages = GielinorDashboardOverlay.farmPages(
            Arrays.asList(
                "Herb · Ardougne · Done",
                "Herb · Catherby · Done",
                "Herb · Falador · Done"),
            2);

        assertEquals(2, pages.size());
        assertEquals("Herbs", pages.get(0).getTitle());
        assertEquals("Herbs", pages.get(1).getTitle());
        assertEquals(Arrays.asList("Falador · Done"), pages.get(1).getLines());
    }
}

