package com.gielinorbriefing;

import com.google.gson.JsonParser;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class SlayerImageServiceTest
{
    @Test
    public void extractsWikiThumbnail()
    {
        String json = "{\"query\":{\"pages\":{\"1\":{\"thumbnail\":"
            + "{\"source\":\"https://example.test/bloodveld.png\"}}}}}";
        assertEquals("https://example.test/bloodveld.png",
            SlayerImageService.thumbnailUrl(new JsonParser().parse(json)));
    }

    @Test
    public void handlesMissingThumbnail()
    {
        assertNull(SlayerImageService.thumbnailUrl(
            new JsonParser().parse("{\"query\":{\"pages\":{}}}")));
    }

    @Test
    public void extractsWikiText()
    {
        String json = "{\"parse\":{\"wikitext\":{\"*\":\"drops here\"}}}";
        assertEquals("drops here", SlayerImageService.wikiText(
            new JsonParser().parse(json)));
    }

    @Test
    public void parsesAndDeduplicatesDropLines()
    {
        String wiki = "{{DropsLine|name=Vile ashes|quantity=1|rarity=Always}}\n"
            + "{{DropsLine|name=Blood rune|quantity=3|rarity=3/128}}\n"
            + "{{DropsLine|name=Blood rune|quantity=30|rarity=1/128}}\n"
            + "{{DropsLine|name=Rune med helm|quantity=1|rarity=1/128}}";
        java.util.List<SlayerImageService.DropCandidate> drops =
            SlayerImageService.parseDrops(wiki);
        assertEquals(2, drops.size());
        assertEquals("Blood rune", drops.get(0).getName());
        assertEquals(30, drops.get(0).getQuantity());
        assertEquals("1/128", drops.get(0).getRarity());
    }

    @Test
    public void parsesTaskGuideFactsAndVariants()
    {
        String wiki = "{{Infobox Slayer\n"
            + "|skillreq = {{SCP|Slayer|92}}\n|combatreq = None\n"
            + "|otherreq = [[Priest in Peril]]\n}}\n"
            + "Araxytes are found in the [[Morytania Spider Cave]]. "
            + "It is recommended to bring [[Extended anti-venom+]] and a [[Seed box]]. "
            + "Players should avoid level 96 araxytes because they cannot spawn a superior.\n"
            + "==Monster Variants==\n{|\n|-\n|[[Araxyte]]\n|96\n|-\n|[[Araxxor]]\n|890\n|}\n"
            + "==Location Comparison==\n{|\n|-\n|[[Morytania Spider Cave]]\n"
            + "|10\n|{{Yes}}\n|{{Yes}}\n|{{Yes}}\n|}\n";

        SlayerImageService.GuideFacts facts = SlayerImageService.parseGuide(wiki);
        assertEquals("92 Slayer | Priest in Peril", facts.getRequirements());
        assertTrue(facts.getLocation().contains("Morytania Spider Cave"));
        assertTrue(facts.getLocation().contains("Cannon Yes"));
        assertEquals("Extended anti-venom+", facts.getGear().get(0));
        assertTrue(facts.getTip().toLowerCase().contains("avoid"));
        assertEquals(2, SlayerImageService.parseVariantPages(wiki).size());
    }

    @Test
    public void parsesRecommendedEquipmentAndInventory()
    {
        String wiki = "==Equipment==\n<tabber>\nCatacombs magic=\n"
            + "{{Equipment\n|align=right\n|head=Slayer helmet (i)\n"
            + "|cape=Imbued saradomin cape\n|weapon=Kodai wand\n"
            + "|hands={{Plink|Bracelet of slaughter}}\n}}\n"
            + "{{Recommended equipment|style=Magic\n"
            + "|head1={{Plink|Slayer helmet (i)}}|head2={{Plink|Virtus mask}}\n"
            + "|weapon1={{Plink|Kodai wand}}|weapon2={{Plink|Ancient sceptre}}}}\n"
            + "{{Inventory|align=right|Dinh's bulwark|Prayer potion|Prayer potion"
            + "||||Herb sack|1=Teleport to house (tablet)}}";
        Map<String, Integer> ids = new HashMap<>();
        ids.put("slayer helmet (i)", 1);
        ids.put("kodai wand", 2);
        ids.put("prayer potion(4)", 3);

        SlayerImageService.Loadout loadout = SlayerImageService.parseLoadout(wiki, ids);

        assertEquals("Catacombs magic", loadout.getLabel());
        assertEquals(4, loadout.getGear().size());
        assertEquals("Slayer helmet (i)", loadout.getGear().get(0).getText());
        assertEquals(1, loadout.getGear().get(0).getItemId());
        assertEquals("Prayer potion ×2", loadout.getInventory().get(1).getText());
        assertEquals(3, loadout.getInventory().get(1).getItemId());
        assertEquals("Magic", loadout.getStyle());
        assertEquals(2, loadout.getRecommendations().size());
        assertEquals("head", loadout.getRecommendations().get(0).getSlot());
        assertEquals("Virtus mask",
            loadout.getRecommendations().get(0).getAlternatives().get(1).getText());
    }

    @Test
    public void identifiesBossVariantsFromMonsterInfobox()
    {
        assertTrue(SlayerImageService.isBossPage(
            "{{Infobox Monster\n|name=Alchemical Hydra\n|cat=Hydras, Bosses\n}}"));
        assertTrue(!SlayerImageService.isBossPage(
            "{{Infobox Monster\n|name=Colossal Hydra\n|cat=Hydras\n}}"));
        assertEquals("Alchemical Hydra", SlayerImageService.parseBossVariantName(
            "A boss variant, the [[Alchemical Hydra]], can be killed in place of normal hydras."));
        assertEquals("Abyssal Sire", SlayerImageService.parseBossVariantName(
            "Players may opt to kill the [[Abyssal Sire]] boss instead."));
    }

    @Test
    public void extractsRepresentativeWikiItemTitle()
    {
        assertEquals("Slayer helmet (i)",
            SlayerImageService.primaryItemTitle("Slayer helmet (i)"));
        assertEquals("Dragon arrow",
            SlayerImageService.primaryItemTitle("Dragon arrow / Ruby dragon bolts (e)"));
        assertEquals("Prayer potion",
            SlayerImageService.primaryItemTitle("Prayer potion ×12"));
    }
}

package com.gielinorbriefing;

import static org.junit.Assert.assertEquals;

import java.util.HashMap;
import java.util.Map;
import java.util.function.IntUnaryOperator;
import org.junit.Test;

public class DailyTaskTrackerTest
{
    @Test
    public void tracksBattlestavesFromRuneLiteVarbits()
    {
        Values values = new Values().varbit(4479, 1).varbit(4539, 0);
        assertEquals(DailyTaskTracker.Status.READY, values.status("Battlestaves"));
        values.varbit(4539, 1);
        assertEquals(DailyTaskTracker.Status.COMPLETE, values.status("Zaff battlestaves"));
    }

    @Test
    public void identifiesLockedAndManualActivities()
    {
        Values values = new Values();
        assertEquals(DailyTaskTracker.Status.UNAVAILABLE, values.status("Battlestaves"));
        assertEquals(DailyTaskTracker.Status.MANUAL, values.status("Kingdom approval"));
    }

    @Test
    public void tracksHerbBoxAllowance()
    {
        Values values = new Values().varp(1060, 10_000).varbit(3961, 14);
        assertEquals(DailyTaskTracker.Status.READY, values.status("Herb boxes"));
        values.varbit(3961, 15);
        assertEquals(DailyTaskTracker.Status.COMPLETE, values.status("Herb boxes"));
    }

    @Test
    public void requiresLoginForAutomaticActivities()
    {
        IntUnaryOperator zero = ignored -> 0;
        assertEquals(DailyTaskTracker.Status.UNKNOWN,
            DailyTaskTracker.evaluate("Sand", false, zero, zero));
    }

    private static final class Values
    {
        private final Map<Integer, Integer> varbits = new HashMap<>();
        private final Map<Integer, Integer> varps = new HashMap<>();

        Values varbit(int id, int value)
        {
            varbits.put(id, value);
            return this;
        }

        Values varp(int id, int value)
        {
            varps.put(id, value);
            return this;
        }

        DailyTaskTracker.Status status(String activity)
        {
            return DailyTaskTracker.evaluate(activity, true,
                id -> varbits.getOrDefault(id, 0), id -> varps.getOrDefault(id, 0));
        }
    }
}

