package com.gielinorbriefing;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class DashboardLayoutTest
{
    @Test
    public void supportsVisibilitySpanAndReordering()
    {
        Map<DashboardWidgetType, Integer> spans = new EnumMap<>(DashboardWidgetType.class);
        DashboardLayoutStore.Layout layout = new DashboardLayoutStore.Layout(
            new ArrayList<>(Arrays.asList(DashboardWidgetType.BANK_HISTORY,
                DashboardWidgetType.NEWS, DashboardWidgetType.SLAYER)),
            EnumSet.of(DashboardWidgetType.BANK_HISTORY, DashboardWidgetType.NEWS), spans);

        assertFalse(layout.isVisible(DashboardWidgetType.SLAYER));
        layout.toggle(DashboardWidgetType.SLAYER);
        assertTrue(layout.isVisible(DashboardWidgetType.SLAYER));

        assertEquals(1, layout.span(DashboardWidgetType.BANK_HISTORY));
        layout.toggleSpan(DashboardWidgetType.BANK_HISTORY);
        assertEquals(2, layout.span(DashboardWidgetType.BANK_HISTORY));
        layout.toggleSpan(DashboardWidgetType.BANK_HISTORY);
        assertEquals(3, layout.span(DashboardWidgetType.BANK_HISTORY));
        layout.toggleSpan(DashboardWidgetType.BANK_HISTORY);
        assertEquals(1, layout.span(DashboardWidgetType.BANK_HISTORY));

        layout.move(DashboardWidgetType.SLAYER, DashboardWidgetType.BANK_HISTORY, false);
        assertEquals(DashboardWidgetType.SLAYER, layout.getOrder().get(0));

        layout.move(DashboardWidgetType.SLAYER, DashboardWidgetType.NEWS, true);
        assertEquals(DashboardWidgetType.SLAYER, layout.getOrder().get(2));
    }
}

package com.gielinorbriefing;

import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.awt.event.MouseWheelEvent;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.MouseListener;
import net.runelite.client.input.MouseWheelListener;

@Singleton
class DashboardInput implements MouseListener, MouseWheelListener, KeyListener
{
    private final GielinorDashboardOverlay overlay;
    private final DashboardButtonOverlay buttonOverlay;
    private DashboardWidgetType pressedWidget;
    private boolean dragged;

    @Inject
    DashboardInput(GielinorDashboardOverlay overlay, DashboardButtonOverlay buttonOverlay)
    {
        this.overlay = overlay;
        this.buttonOverlay = buttonOverlay;
    }

    @Override
    public MouseEvent mouseClicked(MouseEvent event)
    {
        if (!overlay.isOpen() && !event.isAltDown()
            && buttonOverlay.getBounds().contains(event.getPoint()))
        {
            overlay.toggleOpen();
            event.consume();
            return event;
        }
        if (!overlay.isOpen())
        {
            return event;
        }
        if (overlay.getCloseBounds().contains(event.getPoint()))
        {
            overlay.close();
            event.consume();
        }
        else if (overlay.getEditBounds().contains(event.getPoint()))
        {
            overlay.toggleEditing();
            event.consume();
        }
        else if (overlay.getPanelBounds().contains(event.getPoint()))
        {
            DashboardWidgetType type = overlay.widgetAt(event.getX(), event.getY());
            if (!overlay.isEditing() && type != null && event.getButton() == MouseEvent.BUTTON1)
            {
                overlay.activateWidget(type, event.getX(), event.getY());
            }
            event.consume();
        }
        return event;
    }

    @Override
    public MouseEvent mousePressed(MouseEvent event)
    {
        if (overlay.isOpen() && overlay.getPanelBounds().contains(event.getPoint()))
        {
            if (overlay.isEditing())
            {
                pressedWidget = overlay.widgetAt(event.getX(), event.getY());
                if (pressedWidget != null && event.getButton() == MouseEvent.BUTTON1)
                {
                    overlay.beginReorder(pressedWidget);
                }
            }
            dragged = false;
            event.consume();
        }
        return event;
    }

    @Override
    public MouseEvent mouseReleased(MouseEvent event)
    {
        if (pressedWidget != null)
        {
            if (dragged)
            {
                overlay.updateReorder(event.getX(), event.getY());
                overlay.commitReorder();
            }
            else if (event.getButton() == MouseEvent.BUTTON3)
            {
                overlay.toggleSpan(pressedWidget);
            }
            else if (event.getButton() == MouseEvent.BUTTON1)
            {
                overlay.toggleWidget(pressedWidget);
            }
            pressedWidget = null;
            overlay.clearReorder();
            event.consume();
        }
        else if (overlay.isOpen() && overlay.getPanelBounds().contains(event.getPoint()))
        {
            event.consume();
        }
        return event;
    }

    @Override
    public MouseEvent mouseDragged(MouseEvent event)
    {
        if (pressedWidget != null)
        {
            dragged = true;
            overlay.updateReorder(event.getX(), event.getY());
            event.consume();
        }
        return event;
    }

    @Override
    public MouseWheelEvent mouseWheelMoved(MouseWheelEvent event)
    {
        if (overlay.isOpen() && overlay.getPanelBounds().contains(event.getPoint()))
        {
            overlay.scroll(event.getWheelRotation() * 42);
            event.consume();
        }
        return event;
    }

    @Override
    public void keyPressed(KeyEvent event)
    {
        if (overlay.isOpen() && event.getKeyCode() == KeyEvent.VK_ESCAPE)
        {
            overlay.close();
            event.consume();
        }
    }

    @Override
    public void keyTyped(KeyEvent event)
    {
    }

    @Override
    public void keyReleased(KeyEvent event)
    {
    }

    @Override
    public MouseEvent mouseEntered(MouseEvent event)
    {
        return event;
    }

    @Override
    public MouseEvent mouseExited(MouseEvent event)
    {
        return event;
    }

    @Override
    public MouseEvent mouseMoved(MouseEvent event)
    {
        return event;
    }
}

package com.gielinorbriefing;

final class PriceChangeCalculator
{
    private PriceChangeCalculator()
    {
    }

    static double percentChange(long current, long reference)
    {
        if (reference <= 0)
        {
            return 0;
        }

        return ((double) current - reference) * 100.0 / reference;
    }

    static long representativePrice(Long averageHigh, Long averageLow)
    {
        if (averageHigh == null || averageHigh <= 0)
        {
            return averageLow == null ? 0 : Math.max(0, averageLow);
        }
        if (averageLow == null || averageLow <= 0)
        {
            return averageHigh;
        }
        return Math.round((averageHigh + averageLow) / 2.0);
    }
}

