@Slf4j
@Singleton
class SlayerImageService
{
    private static final String API = "https://oldschool.runescape.wiki/api.php";
    private static final String USER_AGENT = "BetterDashboard RuneLite plugin/0.2";
    private static final Pattern DROP_LINE = Pattern.compile("(?m)^\\{\\{DropsLine\\|([^\\r\\n]*)");
    private static final Pattern PARAMETER = Pattern.compile("(?:^|\\|)([a-zA-Z]+)=([^|}]*)");
    private static final Pattern WIKI_LINK = Pattern.compile("\\[\\[([^]|#]+)(?:#[^]|]*)?(?:\\|([^]]+))?]]");
    private static final Pattern INFOBOX_PARAMETER = Pattern.compile(
        "(?m)^\\|\\s*([a-zA-Z]+)\\s*=\\s*(.+)$");
    private static final Pattern LOCATION_ROW = Pattern.compile(
        "(?is)==\\s*Location Comparison\\s*==.*?\\|-\\s*\\|\\s*\\[\\[([^]|#]+).*?(?=\\n\\|-(?:\\n|$)|\\z)");
    private static final Map<String, Requirement> REQUIREMENTS = requirements();

    private final CorePluginBridge bridge;
    private final OkHttpClient httpClient;
    private final ScheduledExecutorService executor;
    private final MarketClient marketClient;
    private final Map<String, BufferedImage> itemImageCache = new ConcurrentHashMap<>();
    private final Set<String> failedItemImages = ConcurrentHashMap.newKeySet();

    private volatile String currentTask;
    private volatile BufferedImage image;
    private volatile BufferedImage bossImage;
    private volatile List<Detail> details = Collections.emptyList();
    private volatile List<Detail> bossDetails = Collections.emptyList();
    private volatile Loadout loadout = Loadout.empty();
    private volatile Loadout bossLoadout = Loadout.empty();
    private volatile String bossVariantName;
    private volatile boolean showingBoss;
    private volatile long imageAttemptAt;

    @Inject
    SlayerImageService(CorePluginBridge bridge, OkHttpClient httpClient,
        ScheduledExecutorService executor, MarketClient marketClient)
    {
        this.bridge = bridge;
        this.httpClient = httpClient;
        this.executor = executor;
        this.marketClient = marketClient;
    }

    BufferedImage getImage()
    {
        refreshTask();
        return showingBoss && bossImage != null ? bossImage : image;
    }

    List<Detail> getDetails()
    {
        refreshTask();
        return showingBoss && !bossDetails.isEmpty() ? bossDetails : details;
    }

    Loadout getLoadout()
    {
        refreshTask();
        return showingBoss && !bossLoadout.isEmpty() ? bossLoadout : loadout;
    }

    String getBossVariantName()
    {
        refreshTask();
        return bossVariantName;
    }

    String getDisplayName()
    {
        return showingBoss && bossVariantName != null ? bossVariantName : currentTask;
    }

    boolean isShowingBoss()
    {
        return showingBoss;
    }

    boolean toggleBossVariant()
    {
        refreshTask();
        if (bossVariantName == null)
        {
            return false;
        }
        showingBoss = !showingBoss;
        return true;
    }

    String getWikiUrl()
    {
        refreshTask();
        String page = showingBoss && bossVariantName != null
            ? bossVariantName + "/Strategies" : "Slayer task/" + currentTask;
        try
        {
            return "https://oldschool.runescape.wiki/w/"
                + URLEncoder.encode(page, StandardCharsets.UTF_8.name())
                    .replace("+", "_").replace("%2F", "/");
        }
        catch (Exception ignored)
        {
            return "https://oldschool.runescape.wiki/w/Slayer_task";
        }
    }

    private void refreshTask()
    {
        String task = bridge.slayerTaskName();
        if (task == null)
        {
            currentTask = null;
            image = null;
            details = Collections.emptyList();
            loadout = Loadout.empty();
            clearBoss();
            return;
        }
        if (!task.equals(currentTask))
        {
            synchronized (this)
            {
                if (!task.equals(currentTask))
                {
                    currentTask = task;
                    image = null;
                    details = Collections.emptyList();
                    loadout = Loadout.empty();
                    clearBoss();
                    imageAttemptAt = System.currentTimeMillis();
                    executor.execute(() -> load(task));
                }
            }
        }
        else if (image == null && System.currentTimeMillis() - imageAttemptAt >= 30_000L)
        {
            synchronized (this)
            {
                if (image == null && System.currentTimeMillis() - imageAttemptAt >= 30_000L)
                {
                    imageAttemptAt = System.currentTimeMillis();
                    executor.execute(() -> loadImage(task));
                }
            }
        }
    }

    private void load(String task)
    {
        loadImage(task);
        loadDetails(task);
    }

    private void clearBoss()
    {
        bossVariantName = null;
        bossImage = null;
        bossDetails = Collections.emptyList();
        bossLoadout = Loadout.empty();
        showingBoss = false;
    }

    private void loadImage(String task)
    {
        try
        {
            String thumbnail = fetchThumbnail(task);
            if (thumbnail == null && task.length() > 1)
            {
                thumbnail = fetchThumbnail(Character.toUpperCase(task.charAt(0))
                    + task.substring(1).toLowerCase());
            }
            if (thumbnail == null)
            {
                thumbnail = fetchThumbnail("Slayer task/" + task);
            }
            if (thumbnail == null && task.length() > 1)
            {
                thumbnail = fetchThumbnail("Slayer task/" + Character.toUpperCase(task.charAt(0))
                    + task.substring(1).toLowerCase());
            }
            if (thumbnail == null)
            {
                return;
            }
            Request imageRequest = new Request.Builder().url(thumbnail)
                .header("User-Agent", USER_AGENT).build();
            BufferedImage loaded;
            try (Response response = httpClient.newCall(imageRequest).execute())
            {
                if (!response.isSuccessful() || response.body() == null)
                {
                    throw new IOException("Wiki image request failed: " + response.code());
                }
                loaded = ImageIO.read(response.body().byteStream());
            }
            if (task.equals(currentTask) && loaded != null)
            {
                image = loaded;
            }
        }
        catch (Exception ex)
        {
            log.debug("Unable to load Slayer task image for {}", task, ex);
        }
    }

    private String fetchThumbnail(String title) throws IOException
    {
        String encoded = URLEncoder.encode(title, StandardCharsets.UTF_8.name())
            .replace("+", "%20");
        Request metadataRequest = new Request.Builder()
            .url(API + "?action=query&prop=pageimages&format=json&pithumbsize=240"
                + "&redirects=1&titles=" + encoded)
            .header("User-Agent", USER_AGENT)
            .build();
        try (Response response = httpClient.newCall(metadataRequest).execute())
        {
            if (!response.isSuccessful() || response.body() == null)
            {
                throw new IOException("Wiki metadata request failed: " + response.code());
            }
            try (InputStreamReader reader = new InputStreamReader(
                response.body().byteStream(), StandardCharsets.UTF_8))
            {
                return thumbnailUrl(new JsonParser().parse(reader));
            }
        }
    }

    private void loadDetails(String task)
    {
        List<Detail> loaded = new ArrayList<>();
        try
        {
            String wikiText = fetchWikiText(task);
            String guideText = fetchWikiText("Slayer task/" + task);
            GuideFacts guide = parseGuide(guideText);
            String detectedBoss = parseBossVariantName(guideText);
            if (task.equals(currentTask) && detectedBoss != null)
            {
                bossVariantName = detectedBoss;
            }
            Requirement requirement = requirementFor(task);
            Map<String, Integer> itemIdsByName = marketClient.fetchItemIdsByName();
            Map<Integer, Long> latestPrices;
            try
            {
                latestPrices = marketClient.fetchLatestPrices();
            }
            catch (IOException ex)
            {
                latestPrices = Collections.emptyMap();
                log.debug("Unable to load prices for Slayer notable drops", ex);
            }
            Loadout parsedLoadout = parseLoadout(guideText, itemIdsByName);
            if (task.equals(currentTask))
            {
                loadout = parsedLoadout;
                hydrateLoadoutImages(task, parsedLoadout);
            }

            loaded.add(new Detail("Req: " + guide.requirements, 0));
            loaded.add(new Detail("Where: " + guide.location, 0));

            List<String> gear = new ArrayList<>();
            int gearItemId = 0;
            if (requirement.itemName != null)
            {
                gear.add(requirement.description);
                gearItemId = itemId(itemIdsByName, requirement.itemName);
            }
            for (String item : guide.gear)
            {
                int resolved = itemId(itemIdsByName, item);
                boolean alreadyDescribed = requirement.itemName != null
                    && requirement.description.toLowerCase().contains(item.toLowerCase());
                if (resolved > 0 && !alreadyDescribed && !containsIgnoreCase(gear, item)
                    && gear.size() < 3)
                {
                    gear.add(item);
                    if (gearItemId == 0)
                    {
                        gearItemId = resolved;
                    }
                }
            }
            String gearText = gear.isEmpty() ? requirement.description : String.join(" / ", gear);
            loaded.add(new Detail("Bring: " + gearText, gearItemId));
            loaded.add(new Detail("Tip: " + guide.tip, 0));
            if (task.equals(currentTask))
            {
                details = Collections.unmodifiableList(new ArrayList<>(loaded));
            }

            List<DropCandidate> candidates = new ArrayList<>(parseDrops(wikiText));
            for (String variant : parseVariantPages(guideText))
            {
                try
                {
                    String variantText = fetchWikiText(variant);
                    if (isBossPage(variantText)
                        || variant.equalsIgnoreCase(bossVariantName))
                    {
                        if (task.equals(currentTask) && bossVariantName == null)
                        {
                            bossVariantName = variant;
                        }
                            loadBossVariant(task, variant, variantText, itemIdsByName,
                                latestPrices, guide);
                    }
                    else
                    {
                        mergeDrops(candidates, parseDrops(variantText));
                    }
                }
                catch (IOException ex)
                {
                    log.debug("Unable to load Slayer variant drops for {}", variant, ex);
                }
            }
            for (DropCandidate candidate : candidates)
            {
                int itemId = itemId(itemIdsByName, candidate.name);
                if (itemId == 0)
                {
                    continue;
                }
                candidate.itemId = itemId;
                long unitPrice = latestPrices.getOrDefault(itemId, 0L);
                candidate.value = (long) Math.max(1, candidate.quantity) * unitPrice;
            }
            candidates.removeIf(candidate -> candidate.itemId <= 0 || candidate.value <= 0);
            candidates.sort(Comparator.comparingLong((DropCandidate value) -> value.value)
                .reversed());

            int count = 0;
            for (DropCandidate candidate : candidates)
            {
                loaded.add(new Detail("Drop: " + candidate.name + " | " + candidate.rarity
                    + " | " + DashboardDataService.formatGp(candidate.value), candidate.itemId));
                if (++count == 2)
                {
                    break;
                }
            }
            if (count == 0)
            {
                loaded.add(new Detail("Drops: No priced notable drops found.", 0));
            }
            if (task.equals(currentTask))
            {
                details = Collections.unmodifiableList(loaded);
            }
        }
        catch (Exception ex)
        {
            log.debug("Unable to load Slayer drops for {}", task, ex);
            loaded.add(new Detail("Drops: Wiki data unavailable.", 0));
            if (task.equals(currentTask))
            {
                details = Collections.unmodifiableList(loaded);
            }
        }
    }

    private void loadBossVariant(String task, String name, String monsterText,
        Map<String, Integer> itemIdsByName, Map<Integer, Long> latestPrices,
        GuideFacts taskGuide)
    {
        String strategy = null;
        try
        {
            strategy = fetchWikiText(name + "/Strategies");
        }
        catch (Exception ex)
        {
            log.debug("Unable to load Slayer boss strategy for {}", name, ex);
        }
        Loadout parsedLoadout = parseLoadout(strategy, itemIdsByName);
        List<Detail> parsedDetails = new ArrayList<>();
        parsedDetails.add(new Detail("Boss variant: " + name, 0));
        String slayerLevel = infoboxValue(monsterText, "slaylvl");
        parsedDetails.add(new Detail("Req: " + (slayerLevel == null
            ? taskGuide.requirements : slayerLevel + " Slayer and current task"), 0));
        parsedDetails.add(new Detail("Where: " + taskGuide.location, 0));
        parsedDetails.add(new Detail("Tip: Click the card for boss gear and inventory.", 0));
        parsedDetails.addAll(pricedDrops(monsterText, itemIdsByName, latestPrices, 2));
        BufferedImage parsedImage = null;
        try
        {
            parsedImage = fetchImage(name);
        }
        catch (Exception ex)
        {
            log.debug("Unable to load Slayer boss image for {}", name, ex);
        }
        if (task.equals(currentTask))
        {
            bossVariantName = name;
            bossLoadout = parsedLoadout;
            bossDetails = Collections.unmodifiableList(parsedDetails);
            bossImage = parsedImage;
            hydrateLoadoutImages(task, parsedLoadout);
        }
    }

    private void hydrateLoadoutImages(String task, Loadout target)
    {
        executor.execute(() ->
        {
            List<Detail> items = new ArrayList<>();
            items.addAll(target.getGear());
            items.addAll(target.getInventory());
            for (RecommendationRow row : target.getRecommendations())
            {
                items.addAll(row.getAlternatives());
            }
            for (Detail item : items)
            {
                if (!task.equals(currentTask) || item.getItemId() > 0 || item.getImage() != null)
                {
                    continue;
                }
                String title = primaryItemTitle(item.getText());
                if (title.isEmpty())
                {
                    continue;
                }
                String key = title.toLowerCase(java.util.Locale.ENGLISH);
                BufferedImage cached = itemImageCache.get(key);
                if (cached != null)
                {
                    item.setImage(cached);
                    continue;
                }
                if (failedItemImages.contains(key))
                {
                    continue;
                }
                try
                {
                    BufferedImage loaded = fetchImage(title);
                    if (loaded != null)
                    {
                        itemImageCache.put(key, loaded);
                        item.setImage(loaded);
                    }
                    else
                    {
                        failedItemImages.add(key);
                    }
                }
                catch (Exception ex)
                {
                    failedItemImages.add(key);
                    log.debug("Unable to load Wiki item image for {}", title, ex);
                }
            }
        });
    }

    static String primaryItemTitle(String label)
    {
        if (label == null)
        {
            return "";
        }
        String title = label.replaceFirst("\\s+×[0-9]+$", "").trim();
        title = title.split("\\s+(?:/|>)\\s+", 2)[0].trim();
        title = title.replaceFirst("(?i)\\s+\\(task only\\)$", "").trim();
        return title;
    }

    private List<Detail> pricedDrops(String wikiText, Map<String, Integer> itemIdsByName,
        Map<Integer, Long> latestPrices, int limit)
    {
        List<DropCandidate> candidates = new ArrayList<>(parseDrops(wikiText));
        for (DropCandidate candidate : candidates)
        {
            candidate.itemId = itemId(itemIdsByName, candidate.name);
            long unitPrice = candidate.itemId <= 0
                ? 0L : latestPrices.getOrDefault(candidate.itemId, 0L);
            candidate.value = (long) Math.max(1, candidate.quantity) * unitPrice;
        }
        candidates.removeIf(candidate -> candidate.itemId <= 0 || candidate.value <= 0);
        candidates.sort(Comparator.comparingLong((DropCandidate value) -> value.value).reversed());
        List<Detail> result = new ArrayList<>();
        for (int index = 0; index < Math.min(limit, candidates.size()); index++)
        {
            DropCandidate candidate = candidates.get(index);
            result.add(new Detail("Drop: " + candidate.name + " | " + candidate.rarity
                + " | " + DashboardDataService.formatGp(candidate.value), candidate.itemId));
        }
        return result;
    }

    private BufferedImage fetchImage(String title) throws IOException
    {
        String thumbnail = fetchThumbnail(title);
        if (thumbnail == null)
        {
            return null;
        }
        Request imageRequest = new Request.Builder().url(thumbnail)
            .header("User-Agent", USER_AGENT).build();
        try (Response response = httpClient.newCall(imageRequest).execute())
        {
            if (!response.isSuccessful() || response.body() == null)
            {
                throw new IOException("Wiki image request failed: " + response.code());
            }
            return ImageIO.read(response.body().byteStream());
        }
    }

    static boolean isBossPage(String wikiText)
    {
        return wikiText != null && Pattern.compile(
            "(?im)^\\|\\s*cat\\s*=.*\\bBosses\\b").matcher(wikiText).find();
    }

    static String parseBossVariantName(String wikiText)
    {
        if (wikiText == null)
        {
            return null;
        }
        Pattern[] patterns = {
            Pattern.compile("(?i)boss variant[^.\\n]{0,180}\\[\\[([^]|#]+)"),
            Pattern.compile("(?i)\\[\\[([^]|#]+)(?:#[^]|]*)?(?:\\|[^]]+)?]]"
                + "[^.\\n]{0,90}\\bboss\\b")
        };
        for (Pattern pattern : patterns)
        {
            Matcher matcher = pattern.matcher(wikiText);
            while (matcher.find())
            {
                String candidate = matcher.group(1).trim();
                String lower = candidate.toLowerCase(java.util.Locale.ENGLISH);
                if (!lower.equals("boss") && !lower.equals("slayer boss")
                    && !lower.contains("boss variant"))
                {
                    return candidate;
                }
            }
        }
        return null;
    }

    private static String infoboxValue(String wikiText, String key)
    {
        if (wikiText == null)
        {
            return null;
        }
        Matcher matcher = Pattern.compile("(?im)^\\|\\s*" + Pattern.quote(key)
            + "\\s*=\\s*([^\\r\\n]+)").matcher(wikiText);
        return matcher.find() ? plainWiki(matcher.group(1)) : null;
    }

    private String fetchWikiText(String title) throws IOException
    {
        String text = fetchWikiTextExact(title);
        if (text != null)
        {
            return text;
        }
        int slash = title.lastIndexOf('/');
        String prefix = slash < 0 ? "" : title.substring(0, slash + 1);
        String name = slash < 0 ? title : title.substring(slash + 1);
        if (name.length() < 2)
        {
            return null;
        }
        return fetchWikiTextExact(prefix + Character.toUpperCase(name.charAt(0))
            + name.substring(1).toLowerCase());
    }

    private String fetchWikiTextExact(String title) throws IOException
    {
        String encoded = URLEncoder.encode(title, StandardCharsets.UTF_8.name())
            .replace("+", "%20");
        Request request = new Request.Builder()
            .url(API + "?action=parse&prop=wikitext&format=json&redirects=1&page=" + encoded)
            .header("User-Agent", USER_AGENT)
            .build();
        try (Response response = httpClient.newCall(request).execute())
        {
            if (!response.isSuccessful() || response.body() == null)
            {
                throw new IOException("Wiki page request failed: " + response.code());
            }
            try (InputStreamReader reader = new InputStreamReader(
                response.body().byteStream(), StandardCharsets.UTF_8))
            {
                return wikiText(new JsonParser().parse(reader));
            }
        }
    }

    static GuideFacts parseGuide(String wikiText)
    {
        if (wikiText == null || wikiText.trim().isEmpty())
        {
            return GuideFacts.unavailable();
        }
        Map<String, String> parameters = new HashMap<>();
        Matcher parameterMatcher = INFOBOX_PARAMETER.matcher(wikiText);
        while (parameterMatcher.find())
        {
            parameters.put(parameterMatcher.group(1).toLowerCase(), parameterMatcher.group(2));
        }

        List<String> requirements = new ArrayList<>();
        addUnlessNone(requirements, plainWiki(parameters.get("skillreq")));
        addUnlessNone(requirements, plainWiki(parameters.get("combatreq")));
        addUnlessNone(requirements, plainWiki(parameters.get("otherreq")));

        Matcher locationMatcher = LOCATION_ROW.matcher(wikiText);
        String location = locationMatcher.find() ? plainWiki(locationMatcher.group(1))
            : linkedLocation(wikiText);
        String locationRow = locationMatcher.find(0) ? locationMatcher.group() : "";
        List<String> yesNo = new ArrayList<>();
        Matcher booleanMatcher = Pattern.compile("\\{\\{(Yes|No)}}", Pattern.CASE_INSENSITIVE)
            .matcher(locationRow);
        while (booleanMatcher.find())
        {
            yesNo.add(booleanMatcher.group(1));
        }
        if (yesNo.size() >= 3)
        {
            location += " | Cannon " + yesNo.get(yesNo.size() - 2)
                + " | Safespot " + yesNo.get(yesNo.size() - 1);
        }

        String lead = leadText(wikiText);
        List<String> gear = linkedGear(lead);
        String tip = interestingTip(lead);
        return new GuideFacts(requirements.isEmpty() ? "No listed requirements"
            : String.join(" | ", requirements), location == null ? "See task guide" : location,
            gear, tip == null ? "Open the Wiki guide for variant and strategy notes" : tip);
    }

    static Loadout parseLoadout(String wikiText, Map<String, Integer> itemIdsByName)
    {
        if (wikiText == null)
        {
            return Loadout.empty();
        }
        int equipmentSection = wikiText.toLowerCase(java.util.Locale.ENGLISH)
            .indexOf("==equipment==");
        String source = equipmentSection >= 0 ? wikiText.substring(equipmentSection) : wikiText;
        String equipment = firstTemplate(source, "Equipment");
        String recommendations = firstTemplate(source, "Recommended equipment");
        if (equipment == null)
        {
            equipment = recommendations;
        }
        String inventory = firstTemplate(source, "Inventory");
        if (equipment == null && inventory == null)
        {
            return Loadout.empty();
        }

        String label = setupLabel(source, equipment);
        List<Detail> gear = equipmentItems(equipment, itemIdsByName);
        List<Detail> supplies = inventoryItems(inventory, itemIdsByName);
        List<RecommendationRow> bestToWorst = recommendationItems(recommendations,
            itemIdsByName);
        String style = recommendationStyle(recommendations);
        return new Loadout(label, style, gear, supplies, bestToWorst);
    }

    private static List<RecommendationRow> recommendationItems(String template,
        Map<String, Integer> itemIdsByName)
    {
        if (template == null)
        {
            return Collections.emptyList();
        }
        Map<String, String> values = new HashMap<>();
        for (String token : templateArguments(template))
        {
            int equals = token.indexOf('=');
            if (equals > 0)
            {
                values.put(token.substring(0, equals).trim().toLowerCase(),
                    token.substring(equals + 1).trim());
            }
        }
        String[] slots = {"head", "neck", "cape", "body", "legs", "weapon", "shield",
            "ammo", "hands", "feet", "ring"};
        List<RecommendationRow> rows = new ArrayList<>();
        for (String slot : slots)
        {
            List<Detail> alternatives = new ArrayList<>();
            for (int rank = 1; rank <= 5; rank++)
            {
                String item = plainItem(values.get(slot + rank));
                if (!item.isEmpty() && !"N/A".equalsIgnoreCase(item)
                    && !"No".equalsIgnoreCase(item))
                {
                    alternatives.add(new Detail(item, itemId(itemIdsByName, item)));
                }
            }
            if (!alternatives.isEmpty())
            {
                rows.add(new RecommendationRow(slot, alternatives));
            }
        }
        return rows;
    }

    private static String recommendationStyle(String template)
    {
        if (template != null)
        {
            for (String token : templateArguments(template))
            {
                int equals = token.indexOf('=');
                if (equals > 0 && "style".equalsIgnoreCase(token.substring(0, equals).trim()))
                {
                    String style = plainWiki(token.substring(equals + 1));
                    if (!style.isEmpty())
                    {
                        return style;
                    }
                }
            }
        }
        return "Recommended";
    }

    private static List<Detail> equipmentItems(String template,
        Map<String, Integer> itemIdsByName)
    {
        if (template == null)
        {
            return Collections.emptyList();
        }
        Map<String, String> values = new HashMap<>();
        for (String token : templateArguments(template))
        {
            int equals = token.indexOf('=');
            if (equals > 0)
            {
                values.put(token.substring(0, equals).trim().toLowerCase(),
                    token.substring(equals + 1).trim());
            }
        }
        String[] slots = {"head", "cape", "neck", "ammo", "weapon", "body",
            "shield", "legs", "hands", "feet", "ring"};
        List<Detail> result = new ArrayList<>();
        for (String slot : slots)
        {
            String raw = values.get(slot);
            if (raw == null)
            {
                raw = values.get(slot + "1");
            }
            addLoadoutItem(result, raw, itemIdsByName);
        }
        return result;
    }

    private static List<Detail> inventoryItems(String template,
        Map<String, Integer> itemIdsByName)
    {
        if (template == null)
        {
            return Collections.emptyList();
        }
        Map<String, Integer> counts = new LinkedHashMap<>();
        for (String token : templateArguments(template))
        {
            String raw = token.trim();
            int equals = raw.indexOf('=');
            if (equals > 0)
            {
                String key = raw.substring(0, equals).trim();
                if ("align".equalsIgnoreCase(key))
                {
                    continue;
                }
                raw = raw.substring(equals + 1).trim();
            }
            String item = plainItem(raw);
            if (!item.isEmpty() && !"N/A".equalsIgnoreCase(item)
                && !"No".equalsIgnoreCase(item))
            {
                counts.put(item, counts.getOrDefault(item, 0) + 1);
            }
        }
        List<Detail> result = new ArrayList<>();
        for (Map.Entry<String, Integer> entry : counts.entrySet())
        {
            int id = itemId(itemIdsByName, entry.getKey());
            String label = entry.getValue() > 1
                ? entry.getKey() + " ×" + entry.getValue() : entry.getKey();
            result.add(new Detail(label, id));
        }
        return result;
    }

    private static void addLoadoutItem(List<Detail> result, String raw,
        Map<String, Integer> itemIdsByName)
    {
        String item = plainItem(raw);
        if (!item.isEmpty() && !"N/A".equalsIgnoreCase(item) && !"No".equalsIgnoreCase(item))
        {
            result.add(new Detail(item, itemId(itemIdsByName, item)));
        }
    }

    private static String plainItem(String raw)
    {
        if (raw == null)
        {
            return "";
        }
        String item = raw.replaceAll("(?i)\\{\\{plink\\|([^|}]+)(?:\\|[^}]*)?}}", "$1");
        return plainWiki(item).replaceAll("\\s*\\(task only\\)\\s*$", "").trim();
    }

    private static String firstTemplate(String source, String name)
    {
        Matcher matcher = Pattern.compile("(?i)\\{\\{" + Pattern.quote(name) + "(?=\\s|\\|)")
            .matcher(source);
        if (!matcher.find())
        {
            return null;
        }
        int start = matcher.start();
        int depth = 0;
        for (int index = start; index + 1 < source.length(); index++)
        {
            String pair = source.substring(index, index + 2);
            if ("{{".equals(pair))
            {
                depth++;
                index++;
            }
            else if ("}}".equals(pair))
            {
                depth--;
                index++;
                if (depth == 0)
                {
                    return source.substring(start, index + 1);
                }
            }
        }
        return null;
    }

    private static List<String> templateArguments(String template)
    {
        if (template == null)
        {
            return Collections.emptyList();
        }
        int firstPipe = template.indexOf('|');
        int end = template.length() - 2;
        if (firstPipe < 0 || end <= firstPipe)
        {
            return Collections.emptyList();
        }
        List<String> result = new ArrayList<>();
        StringBuilder value = new StringBuilder();
        int braces = 0;
        int links = 0;
        for (int index = firstPipe + 1; index < end; index++)
        {
            char current = template.charAt(index);
            char next = index + 1 < end ? template.charAt(index + 1) : 0;
            if (current == '{' && next == '{')
            {
                braces++;
            }
            else if (current == '}' && next == '}' && braces > 0)
            {
                braces--;
            }
            else if (current == '[' && next == '[')
            {
                links++;
            }
            else if (current == ']' && next == ']' && links > 0)
            {
                links--;
            }
            if (current == '|' && braces == 0 && links == 0)
            {
                result.add(value.toString().trim());
                value.setLength(0);
            }
            else
            {
                value.append(current);
            }
        }
        result.add(value.toString().trim());
        return result;
    }

    private static String setupLabel(String source, String equipment)
    {
        if (equipment == null)
        {
            return "Recommended setup";
        }
        int index = source.indexOf(equipment);
        String before = index <= 0 ? "" : source.substring(0, index).trim();
        int lineStart = before.lastIndexOf('\n');
        String line = before.substring(lineStart + 1).trim();
        if (line.endsWith("=") && !line.startsWith("|"))
        {
            line = line.substring(0, line.length() - 1).trim();
            if (!line.isEmpty() && line.length() < 50)
            {
                return plainWiki(line);
            }
        }
        return "Recommended setup";
    }

    private static String leadText(String wikiText)
    {
        Matcher infobox = Pattern.compile("(?ms)^\\{\\{Infobox Slayer.*?^}}\\s*").matcher(wikiText);
        String withoutInfobox = infobox.find() ? wikiText.substring(infobox.end()) : wikiText;
        int section = withoutInfobox.indexOf("\n==");
        return section < 0 ? withoutInfobox : withoutInfobox.substring(0, section);
    }

    private static List<String> linkedGear(String lead)
    {
        List<String> result = new ArrayList<>();
        for (String sentence : lead.split("(?<=[.!?])\\s+"))
        {
            String lower = sentence.toLowerCase();
            if (!(lower.contains("required") || lower.contains("recommended")
                || lower.contains("bring") || lower.contains("wear")
                || lower.contains("equip") || lower.contains("immunity")))
            {
                continue;
            }
            Matcher links = WIKI_LINK.matcher(sentence);
            while (links.find() && result.size() < 8)
            {
                String item = plainWiki(links.group(2) == null ? links.group(1) : links.group(2));
                if (looksLikeItem(item) && !containsIgnoreCase(result, item))
                {
                    result.add(item);
                }
            }
        }
        return result;
    }

    private static boolean looksLikeItem(String value)
    {
        String lower = value.toLowerCase();
        return !(lower.contains("slayer") || lower.contains("diary")
            || lower.contains("dungeon") || lower.contains("cave")
            || lower.contains("prayer") || lower.contains("combat")
            || lower.contains("player") || lower.contains("monster")
            || lower.contains("task") || lower.contains("defence")
            || lower.contains("hitpoints") || lower.contains("location"));
    }

    private static String interestingTip(String lead)
    {
        String best = null;
        int bestScore = 0;
        for (String raw : lead.split("(?<=[.!?])\\s+"))
        {
            String sentence = plainWiki(raw);
            String lower = sentence.toLowerCase();
            int score = (lower.contains("avoid") ? 8 : 0)
                + (lower.contains("superior") ? 5 : 0)
                + (lower.contains("boss variant") ? 5 : 0)
                + (lower.contains("profitable") ? 4 : 0)
                + (lower.contains("cannon") ? 3 : 0)
                + (lower.contains("safespot") ? 3 : 0)
                + (lower.contains("experience") ? 2 : 0);
            if (score > bestScore && sentence.length() > 15)
            {
                best = shorten(sentence, 150);
                bestScore = score;
            }
        }
        return best;
    }

    private static String linkedLocation(String wikiText)
    {
        Matcher links = WIKI_LINK.matcher(leadText(wikiText));
        while (links.find())
        {
            String value = plainWiki(links.group(2) == null ? links.group(1) : links.group(2));
            String lower = value.toLowerCase();
            if (lower.contains("dungeon") || lower.contains("cave")
                || lower.contains("tower") || lower.contains("laborator")
                || lower.contains("catacomb") || lower.contains("island"))
            {
                return value;
            }
        }
        return null;
    }

    static String plainWiki(String value)
    {
        if (value == null)
        {
            return null;
        }
        String plain = value.replaceAll("\\{\\{SCP\\|([^|}]+)\\|([^|}]+)(?:\\|[^}]*)?}}", "$2 $1");
        Matcher links = WIKI_LINK.matcher(plain);
        StringBuffer buffer = new StringBuffer();
        while (links.find())
        {
            links.appendReplacement(buffer, Matcher.quoteReplacement(
                links.group(2) == null ? links.group(1) : links.group(2)));
        }
        links.appendTail(buffer);
        return buffer.toString().replaceAll("\\{\\{[^{}]*}}", "")
            .replace("'''", "").replace("''", "").replaceAll("<[^>]+>", "")
            .replaceAll("\\s+", " ").trim();
    }

    private static void addUnlessNone(List<String> values, String value)
    {
        if (value != null && !value.isEmpty() && !"None".equalsIgnoreCase(value))
        {
            values.add(value);
        }
    }

    private static boolean containsIgnoreCase(List<String> values, String candidate)
    {
        for (String value : values)
        {
            if (value.equalsIgnoreCase(candidate))
            {
                return true;
            }
        }
        return false;
    }

    private static String shorten(String value, int limit)
    {
        return value.length() <= limit ? value : value.substring(0, limit - 1).trim() + "…";
    }

    private static int itemId(Map<String, Integer> itemIdsByName, String name)
    {
        if (name == null)
        {
            return 0;
        }
        String normalized = name.toLowerCase(java.util.Locale.ENGLISH).trim();
        Integer value = itemIdsByName.get(normalized);
        if (value == null && !normalized.matches(".*\\([1-4]\\)$"))
        {
            for (int dose = 4; dose >= 1 && value == null; dose--)
            {
                value = itemIdsByName.get(normalized + "(" + dose + ")");
            }
        }
        return value == null ? 0 : value;
    }

    static String wikiText(JsonElement root)
    {
        if (root == null || !root.isJsonObject())
        {
            return null;
        }
        JsonObject parse = root.getAsJsonObject().getAsJsonObject("parse");
        JsonObject wikitext = parse == null ? null : parse.getAsJsonObject("wikitext");
        return wikitext == null || !wikitext.has("*") ? null
            : wikitext.get("*").getAsString();
    }

    static List<DropCandidate> parseDrops(String wikiText)
    {
        if (wikiText == null)
        {
            return Collections.emptyList();
        }
        Map<String, DropCandidate> unique = new LinkedHashMap<>();
        Matcher lines = DROP_LINE.matcher(wikiText);
        while (lines.find())
        {
            Map<String, String> values = new HashMap<>();
            Matcher parameters = PARAMETER.matcher(lines.group(1));
            while (parameters.find())
            {
                values.put(parameters.group(1).toLowerCase(), parameters.group(2).trim());
            }
            String name = values.get("name");
            String rarity = values.get("rarity");
            if (name == null || rarity == null || "always".equalsIgnoreCase(rarity)
                || name.equalsIgnoreCase("Coins") || name.endsWith(" bones"))
            {
                continue;
            }
            int quantity = firstNumber(values.get("quantity"));
            DropCandidate existing = unique.get(name.toLowerCase());
            DropCandidate candidate = new DropCandidate(name, Math.max(1, quantity), rarity);
            if (existing == null || candidate.quantity > existing.quantity)
            {
                unique.put(name.toLowerCase(), candidate);
            }
        }
        return new ArrayList<>(unique.values());
    }

    static List<String> parseVariantPages(String wikiText)
    {
        if (wikiText == null)
        {
            return Collections.emptyList();
        }
        Matcher section = Pattern.compile("(?is)==\\s*Monster Variants\\s*==(.*?)(?=\\n==|\\z)")
            .matcher(wikiText);
        if (!section.find())
        {
            return Collections.emptyList();
        }
        List<String> result = new ArrayList<>();
        Matcher rows = Pattern.compile("(?m)^\\|\\s*\\[\\[([^]|#]+)").matcher(section.group(1));
        while (rows.find() && result.size() < 3)
        {
            String page = rows.group(1).trim();
            if (!containsIgnoreCase(result, page))
            {
                result.add(page);
            }
        }
        return result;
    }

    private static void mergeDrops(List<DropCandidate> target, List<DropCandidate> additions)
    {
        for (DropCandidate addition : additions)
        {
            DropCandidate existing = null;
            for (DropCandidate candidate : target)
            {
                if (candidate.name.equalsIgnoreCase(addition.name))
                {
                    existing = candidate;
                    break;
                }
            }
            if (existing == null)
            {
                target.add(addition);
            }
            else if (addition.quantity > existing.quantity)
            {
                target.remove(existing);
                target.add(addition);
            }
        }
    }

    private static int firstNumber(String value)
    {
        if (value == null)
        {
            return 1;
        }
        Matcher number = Pattern.compile("[0-9][0-9,]*").matcher(value);
        if (!number.find())
        {
            return 1;
        }
        try
        {
            return Integer.parseInt(number.group().replace(",", ""));
        }
        catch (NumberFormatException ignored)
        {
            return 1;
        }
    }

