    static String thumbnailUrl(JsonElement root)
    {
        if (root == null || !root.isJsonObject())
        {
            return null;
        }
        JsonObject query = root.getAsJsonObject().getAsJsonObject("query");
        JsonObject pages = query == null ? null : query.getAsJsonObject("pages");
        if (pages == null)
        {
            return null;
        }
        for (Map.Entry<String, JsonElement> page : pages.entrySet())
        {
            JsonObject value = page.getValue().getAsJsonObject();
            JsonObject thumbnail = value.getAsJsonObject("thumbnail");
            if (thumbnail != null && thumbnail.has("source"))
            {
                return thumbnail.get("source").getAsString();
            }
        }
        return null;
    }
