@Singleton
class DashboardButtonOverlay extends Overlay
{
    static final int SIZE = 27;
    private final Client client;
    private final GielinorDashboardOverlay dashboard;
    private final GielinorBriefingConfig config;

    @Inject
    DashboardButtonOverlay(Client client, GielinorDashboardOverlay dashboard,
        GielinorBriefingConfig config)
    {
        this.client = client;
        this.dashboard = dashboard;
        this.config = config;
        setPosition(OverlayPosition.CANVAS_TOP_RIGHT);
        setPreferredPosition(OverlayPosition.CANVAS_TOP_RIGHT);
        setLayer(OverlayLayer.ALWAYS_ON_TOP);
        setPriority(PRIORITY_HIGHEST);
        setMovable(true);
        // Snap corners in fixed mode are anchored to the 3D viewport, which prevents the
        // launcher from being released over the minimap/inventory side of the game canvas.
        // Keep native Alt-dragging, but allow a genuinely free full-canvas position.
        setSnappable(false);
        setResettable(true);
    }

    @Override
    public String getName()
    {
        // Stable, distinct persistence key for the canvas-corner launcher placement.
        return "Better Dashboard Launcher";
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (client.getGameState() != GameState.LOGGED_IN || dashboard.isOpen())
        {
            return null;
        }
        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
            RenderingHints.VALUE_ANTIALIAS_ON);
        int diameter = SIZE - 3;
        graphics.setColor(new Color(0, 0, 0, 175));
        graphics.fillOval(2, 3, diameter, diameter);
        DashboardTheme theme = config.dashboardTheme() == null
            ? DashboardTheme.GIELINOR : config.dashboardTheme();
        Color surface = dashboard.isOpen() ? theme.cardTop() : theme.card();
        graphics.setColor(new Color(surface.getRed(), surface.getGreen(), surface.getBlue(), 245));
        graphics.fillOval(0, 0, diameter, diameter);
        graphics.setColor(theme.primary());
        graphics.setStroke(new BasicStroke(1.5f));
        graphics.drawOval(1, 1, diameter - 2, diameter - 2);
        for (int row = 0; row < 2; row++)
        {
            for (int column = 0; column < 2; column++)
            {
                graphics.drawRoundRect(6 + column * 7, 6 + row * 7, 5, 5, 1, 1);
            }
        }
        return new Dimension(SIZE, SIZE);
    }
}

