import okhttp3.Response;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;
import org.xml.sax.SAXException;

@Singleton
class NewsClient
{
    private static final String NEWS_URL =
        "https://secure.runescape.com/m=news/latest_news.rss?oldschool=true";
    private static final int SUMMARY_LIMIT = 155;

    private final OkHttpClient httpClient;

    @Inject
    NewsClient(OkHttpClient httpClient)
    {
        this.httpClient = httpClient;
    }

    List<NewsItem> fetch() throws IOException
    {
        Request request = new Request.Builder()
            .url(NEWS_URL)
            .header("User-Agent", "BetterDashboard RuneLite plugin/0.2")
            .build();

        try (Response response = httpClient.newCall(request).execute())
        {
            if (!response.isSuccessful() || response.body() == null)
            {
                throw new IOException("News request failed with HTTP " + response.code());
            }

            try (InputStream input = response.body().byteStream())
            {
                return parse(input);
            }
        }
    }

    static List<NewsItem> parse(InputStream input) throws IOException
    {
        try
        {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            secure(factory);
            NodeList itemNodes = factory.newDocumentBuilder().parse(input).getElementsByTagName("item");
            List<NewsItem> items = new ArrayList<>();

            for (int i = 0; i < itemNodes.getLength(); i++)
            {
                Element item = (Element) itemNodes.item(i);
                String title = childText(item, "title");
                if (title.isEmpty())
                {
                    continue;
                }

                items.add(new NewsItem(
                    title,
                    summarize(childText(item, "description")),
                    childText(item, "link"),
                    parseDate(childText(item, "pubDate"))));
            }

            items.sort(Comparator.comparing(NewsItem::getPublishedAt,
                Comparator.nullsLast(Comparator.reverseOrder())));
            return Collections.unmodifiableList(items);
        }
        catch (ParserConfigurationException | SAXException ex)
        {
            throw new IOException("Unable to parse the OSRS news feed", ex);
        }
    }

    private static void secure(DocumentBuilderFactory factory) throws ParserConfigurationException
    {
        factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        factory.setXIncludeAware(false);
        factory.setExpandEntityReferences(false);
    }

    private static String childText(Element element, String tag)
    {
        NodeList nodes = element.getElementsByTagName(tag);
        return nodes.getLength() == 0 ? "" : nodes.item(0).getTextContent().trim();
    }

    static String summarize(String html)
    {
        String plain = html
            .replaceAll("(?is)<script.*?</script>", " ")
            .replaceAll("(?s)<[^>]*>", " ")
            .replace("&nbsp;", " ")
            .replace("&amp;", "&")
            .replaceAll("\\s+", " ")
            .trim();

        if (plain.length() <= SUMMARY_LIMIT)
        {
            return plain;
        }

        int end = plain.lastIndexOf(' ', SUMMARY_LIMIT - 1);
        return plain.substring(0, Math.max(80, end)) + "…";
    }

    private static Instant parseDate(String value)
    {
        try
        {
            return ZonedDateTime.parse(value, DateTimeFormatter.RFC_1123_DATE_TIME).toInstant();
        }
        catch (DateTimeParseException ex)
        {
            return null;
        }
    }
}

