            PricePoint currentPoint = entry.getValue();
            PricePoint referencePoint = daily.get(itemId);
            if (referencePoint == null)
            {
                continue;
            }

            long current = currentPoint.getPrice();
            long reference = referencePoint.getPrice();
            long volume = referencePoint.getVolume();
            double percent = PriceChangeCalculator.percentChange(current, reference);

            if (current > 0 && reference > 0 && volume >= minimumDailyVolume
                && Math.abs(percent) <= 50)
            {
                liquidReturns.add(percent);
                if (percent > 0.25)
                {
                    rising++;
                }
                else if (percent < -0.25)
                {
                    falling++;
                }
                else
                {
                    flat++;
                }
            }

        }

        for (Map.Entry<Integer, PricePoint> entry : latest.entrySet())
        {
            int itemId = entry.getKey();
            PricePoint referencePoint = daily.get(itemId);
            if (referencePoint == null)
            {
                continue;
            }
            long current = entry.getValue().getPrice();
            long reference = referencePoint.getPrice();
            long volume = referencePoint.getVolume();
            long gpChange = current - reference;
            double percent = PriceChangeCalculator.percentChange(current, reference);
            boolean significant = Math.abs(percent) >= minimumPercent
                || safeAbs(gpChange) >= minimumValuableSwing;
            if (current <= 0 || reference <= 0 || current < minimumItemValue
                || volume < minimumValuableVolume || Math.abs(gpChange) < minimumGpChange
                || !significant || Math.abs(percent) > 60)
            {
                continue;
            }
            candidates.add(new MarketMover(itemId, names.getOrDefault(itemId, "Item " + itemId),
                current, reference, volume, gpChange, percent));
        }

        candidates.sort(Comparator.comparingLong(
            (MarketMover mover) -> safeAbs(mover.getGpChange())).reversed());
        List<MarketMover> gainers = new ArrayList<>();
        List<MarketMover> losers = new ArrayList<>();
        for (MarketMover mover : candidates)
        {
            if (gainers.size() + losers.size() >= limit)
            {
                break;
            }
            if (mover.getPercentChange() > 0)
            {
                gainers.add(mover);
            }
            else if (mover.getPercentChange() < 0)
            {
                losers.add(mover);
            }
        }

        List<BankMover> bankMovers = calculateBankMovers(
            bankQuantities, names, latest, daily, bankLimit);
        MarketPulse pulse = calculatePulse(liquidReturns, rising, falling, flat);
        List<WatchlistItem> watchlist = calculateWatchlist(
            watchlistConfig, names, latest, daily);

        return new MoverLists(
            Collections.unmodifiableList(gainers),
            Collections.unmodifiableList(losers),
            Collections.unmodifiableList(bankMovers),
            pulse,
            Collections.unmodifiableList(watchlist));
    }

    private static MarketPulse calculatePulse(List<Double> returns, int rising, int falling, int flat)
    {
        if (returns.isEmpty())
        {
            return MarketPulse.EMPTY;
        }
        Collections.sort(returns);
        int middle = returns.size() / 2;
        double median = returns.size() % 2 == 0
            ? (returns.get(middle - 1) + returns.get(middle)) / 2.0
            : returns.get(middle);
        return new MarketPulse(median, rising, falling, flat, returns.size(),
            Collections.emptyList());
    }

    private static List<WatchlistItem> calculateWatchlist(
        String configured,
        Map<Integer, String> names,
        Map<Integer, PricePoint> recent,
        Map<Integer, PricePoint> daily)
    {
        Map<String, Integer> idsByName = new HashMap<>();
        names.forEach((id, name) -> idsByName.put(name.toLowerCase(Locale.ENGLISH), id));
        List<WatchlistItem> result = new ArrayList<>();
        Set<Integer> seen = new HashSet<>();

        for (String token : configured.split(","))
        {
            String value = token.trim();
            if (value.isEmpty())
            {
                continue;
            }

            Integer itemId;
            try
            {
                itemId = Integer.parseInt(value);
            }
            catch (NumberFormatException ex)
            {
                itemId = idsByName.get(value.toLowerCase(Locale.ENGLISH));
            }
            if (itemId == null || !seen.add(itemId))
            {
                continue;
            }

            PricePoint current = recent.get(itemId);
            PricePoint reference = daily.get(itemId);
            if (current == null || reference == null || current.price <= 0 || reference.price <= 0)
            {
                continue;
            }
            long gpChange = current.price - reference.price;
            result.add(new WatchlistItem(itemId, names.getOrDefault(itemId, value), current.price,
                gpChange, PriceChangeCalculator.percentChange(current.price, reference.price)));
            if (result.size() == 12)
            {
                break;
            }
        }
        return result;
    }

    private static List<BankMover> calculateBankMovers(
        Map<Integer, Long> bankQuantities,
        Map<Integer, String> names,
        Map<Integer, PricePoint> recent,
        Map<Integer, PricePoint> daily,
        int limit)
    {
        List<BankMover> movers = new ArrayList<>();
        for (Map.Entry<Integer, Long> bankItem : bankQuantities.entrySet())
        {
            int itemId = bankItem.getKey();
            PricePoint currentPoint = recent.get(itemId);
            PricePoint referencePoint = daily.get(itemId);
            if (currentPoint == null || referencePoint == null
                || currentPoint.getPrice() <= 0 || referencePoint.getPrice() <= 0)
            {
                continue;
            }

            long unitChange = currentPoint.getPrice() - referencePoint.getPrice();
            if (unitChange == 0)
            {
                continue;
            }
            long totalChange = saturatingMultiply(unitChange, bankItem.getValue());
            movers.add(new BankMover(
                itemId,
                names.getOrDefault(itemId, "Item " + itemId),
                bankItem.getValue(),
                currentPoint.getPrice(),
                unitChange,
                totalChange,
                PriceChangeCalculator.percentChange(currentPoint.getPrice(), referencePoint.getPrice())));
        }

        movers.sort(Comparator.comparingLong((BankMover mover) -> safeAbs(mover.getTotalGpChange()))
            .reversed());
        return new ArrayList<>(movers.subList(0, Math.min(limit, movers.size())));
    }

    private static long saturatingMultiply(long left, long right)
    {
        try
        {
            return Math.multiplyExact(left, right);
        }
        catch (ArithmeticException ex)
        {
            return left < 0 ? Long.MIN_VALUE : Long.MAX_VALUE;
        }
    }

    private static long safeAbs(long value)
    {
        return value == Long.MIN_VALUE ? Long.MAX_VALUE : Math.abs(value);
    }

    synchronized Map<Integer, String> fetchNames() throws IOException
    {
        if (cachedNames != null)
        {
            return cachedNames;
        }
        JsonElement root = getJson("mapping");
        Map<Integer, String> names = new HashMap<>();
        for (JsonElement element : root.getAsJsonArray())
        {
            JsonObject item = element.getAsJsonObject();
            names.put(item.get("id").getAsInt(), item.get("name").getAsString());
        }
        cachedNames = Collections.unmodifiableMap(names);
        return cachedNames;
    }

    Map<String, Integer> fetchItemIdsByName() throws IOException
    {
        Map<String, Integer> result = new HashMap<>();
        fetchNames().forEach((id, name) -> result.put(name.toLowerCase(Locale.ENGLISH), id));
        return result;
    }

    Map<Integer, Long> fetchLatestPrices() throws IOException
    {
        Map<Integer, Long> result = new HashMap<>();
        fetchPrices("latest").forEach((id, point) -> result.put(id, point.getPrice()));
        return result;
    }

    private Map<Integer, PricePoint> fetchPrices(String period) throws IOException
    {
        JsonObject data = getJson(period).getAsJsonObject().getAsJsonObject("data");
        Map<Integer, PricePoint> prices = new HashMap<>();
        for (Map.Entry<String, JsonElement> entry : data.entrySet())
        {
            JsonObject value = entry.getValue().getAsJsonObject();
            Long high = nullableLong(value, "latest".equals(period) ? "high" : "avgHighPrice");
            Long low = nullableLong(value, "latest".equals(period) ? "low" : "avgLowPrice");
            long price = PriceChangeCalculator.representativePrice(high, low);
            long volume = value.has("highPriceVolume") ? value.get("highPriceVolume").getAsLong() : 0;
            volume += value.has("lowPriceVolume") ? value.get("lowPriceVolume").getAsLong() : 0;
            prices.put(Integer.parseInt(entry.getKey()), new PricePoint(price, volume));
        }
        return prices;
    }

    private JsonElement getJson(String path) throws IOException
    {
        Request request = new Request.Builder()
            .url(API_ROOT + path)
            .header("User-Agent", USER_AGENT)
            .build();

        try (Response response = httpClient.newCall(request).execute())
        {
            if (!response.isSuccessful() || response.body() == null)
            {
                throw new IOException("Price request failed with HTTP " + response.code());
            }
            try (InputStreamReader reader = new InputStreamReader(
                response.body().byteStream(), StandardCharsets.UTF_8))
            {
                return new JsonParser().parse(reader);
            }
        }
    }

    private static Long nullableLong(JsonObject object, String name)
    {
        JsonElement value = object.get(name);
        return value == null || value.isJsonNull() ? null : value.getAsLong();
    }

    @Value
    static class MoverLists
    {
        List<MarketMover> gainers;
        List<MarketMover> losers;
        List<BankMover> bankMovers;
        MarketPulse marketPulse;
        List<WatchlistItem> watchlist;
    }

    @Value
    private static class PricePoint
    {
        long price;
        long volume;
    }
}

package com.gielinorbriefing;

import com.google.inject.Provides;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PlayerLootReceived;
import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.loottracker.PluginLootReceived;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
    name = "Better Dashboard",
    description = "Bank value, GE movers, Slayer guides, farm runs, dailies, progress, and news in one configurable dashboard",
    tags = {"account", "overview", "dashboard", "bank", "ge", "prices", "market",
        "slayer", "farming", "farm", "birdhouse", "dailies", "tracker", "news",
        "xp", "loot", "goals", "timers"}
)
public class GielinorBriefingPlugin extends Plugin
{
    @Inject private OverlayManager overlayManager;
    @Inject private GielinorDashboardOverlay overlay;
    @Inject private DashboardButtonOverlay buttonOverlay;
    @Inject private DashboardInput dashboardInput;
    @Inject private MouseManager mouseManager;
    @Inject private KeyManager keyManager;
    @Inject private BriefingService briefingService;
    @Inject private DashboardDataService dashboardDataService;
    @Inject private BankPortfolioStore bankPortfolioStore;
    @Inject private BankHistoryStore bankHistoryStore;
    @Inject private SessionLootStore lootStore;
    @Inject private ScheduledExecutorService executor;
    @Inject private ConfigManager configManager;

    private ScheduledFuture<?> bankValuationTask;
    private ScheduledFuture<?> bankSyncTask;

    @Override
    protected void startUp()
    {
        overlayManager.add(overlay);
        overlayManager.add(buttonOverlay);
        mouseManager.registerMouseListener(dashboardInput);
        mouseManager.registerMouseWheelListener(dashboardInput);
        keyManager.registerKeyListener(dashboardInput);
        briefingService.start();
        bankValuationTask = executor.scheduleWithFixedDelay(
            dashboardDataService::recordHourlyBankValue, 5, 60, TimeUnit.MINUTES);
    }

    @Override
    protected void shutDown()
    {
        if (bankValuationTask != null)
        {
            bankValuationTask.cancel(false);
            bankValuationTask = null;
        }
        if (bankSyncTask != null)
        {
            bankSyncTask.cancel(false);
            bankSyncTask = null;
        }
        briefingService.stop();
        keyManager.unregisterKeyListener(dashboardInput);
        mouseManager.unregisterMouseWheelListener(dashboardInput);
        mouseManager.unregisterMouseListener(dashboardInput);
        overlayManager.remove(overlay);
        overlayManager.remove(buttonOverlay);
        overlay.close();
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!GielinorBriefingConfig.GROUP.equals(event.getGroup()))
        {
            return;
        }
        if (DashboardLayoutStore.isVisibilityKey(event.getKey()))
        {
            overlay.reloadLayout();
        }
        if ("clearBankHistory".equals(event.getKey())
            && Boolean.parseBoolean(event.getNewValue()))
        {
            bankHistoryStore.clear();
            configManager.setConfiguration(GielinorBriefingConfig.GROUP,
                "clearBankHistory", false);
        }
        if (!DashboardLayoutStore.ORDER_KEY.equals(event.getKey())
            && !DashboardLayoutStore.VISIBLE_KEY.equals(event.getKey())
            && !DashboardLayoutStore.SPANS_KEY.equals(event.getKey()))
        {
            briefingService.refreshSoon();
        }
        dashboardDataService.invalidate();
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (event.getContainerId() == InventoryID.BANK)
        {
            bankPortfolioStore.capture(event.getItemContainer());
            if (bankSyncTask != null)
            {
                bankSyncTask.cancel(false);
            }
            bankSyncTask = executor.schedule(dashboardDataService::bankSynchronized,
                1, TimeUnit.SECONDS);
        }
    }

    @Subscribe
    public void onServerNpcLoot(ServerNpcLoot event)
    {
        lootStore.add(event.getComposition().getName(), event.getItems());
        dashboardDataService.invalidate();
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged event)
    {
        dashboardDataService.invalidate();
    }

    @Subscribe
    public void onPlayerLootReceived(PlayerLootReceived event)
    {
        lootStore.add(event.getPlayer().getName(), event.getItems());
        dashboardDataService.invalidate();
    }

    @Subscribe
    public void onPluginLootReceived(PluginLootReceived event)
    {
        lootStore.add(event.getName(), event.getItems());
        dashboardDataService.invalidate();
    }

    @Provides
    GielinorBriefingConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(GielinorBriefingConfig.class);
    }
}

