package com.gielinorbriefing;

import java.util.Locale;
import java.util.function.IntUnaryOperator;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;

/** Reads the same game values as RuneLite's built-in Daily Task Indicators plugin. */
@Singleton
class DailyTaskTracker
{
    private final Client client;

    @Inject
    DailyTaskTracker(Client client)
    {
        this.client = client;
    }

    Status status(String activity)
    {
        return evaluate(activity, client.getGameState() == GameState.LOGGED_IN,
            client::getVarbitValue, client::getVarpValue);
    }

    boolean isAutoTracked(String activity)
    {
        return rule(activity) != Rule.MANUAL;
    }

    static Status evaluate(String activity, boolean loggedIn, IntUnaryOperator varbit,
        IntUnaryOperator varp)
    {
        Rule rule = rule(activity);
        if (rule == Rule.MANUAL)
        {
            return Status.MANUAL;
        }
        if (!loggedIn)
        {
            return Status.UNKNOWN;
        }

        switch (rule)
        {
            case BATTLESTAVES:
                return claimed(varbit, 4479, 4539);
            case ESSENCE:
                return claimed(varbit, 4459, 4547);
            case RUNES:
                return claimed(varbit, 4466, 4540);
            case FLAX:
                return claimed(varbit, 4475, 4559);
            case ARROWS:
                return claimed(varbit, 4471, 4563);
            case DYNAMITE:
                return claimed(varbit, 7926, 7939);
            case HERB_BOXES:
                if (varbit.applyAsInt(1777) != 0 || varp.applyAsInt(1060) < 9_500)
                {
                    return Status.UNAVAILABLE;
                }
                return varbit.applyAsInt(3961) < 15 ? Status.READY : Status.COMPLETE;
            case SAND:
                if (varbit.applyAsInt(1777) == 2 || varbit.applyAsInt(1527) < 160)
                {
                    return Status.UNAVAILABLE;
                }
                return varbit.applyAsInt(4549) == 0 ? Status.READY : Status.COMPLETE;
            case BONEMEAL:
                if (varbit.applyAsInt(4488) != 1)
                {
                    return Status.UNAVAILABLE;
                }
                int allowance = 13;
                if (varbit.applyAsInt(4489) == 1)
                {
                    allowance += 13;
                    if (varbit.applyAsInt(4490) == 1)
                    {
                        allowance += 13;
                    }
                }
                return varbit.applyAsInt(4543) < allowance ? Status.READY : Status.COMPLETE;
            default:
                return Status.MANUAL;
        }
    }

    private static Status claimed(IntUnaryOperator varbit, int unlockVarbit, int claimVarbit)
    {
        if (varbit.applyAsInt(unlockVarbit) != 1)
        {
            return Status.UNAVAILABLE;
        }
        return varbit.applyAsInt(claimVarbit) == 0 ? Status.READY : Status.COMPLETE;
    }

    private static Rule rule(String activity)
    {
        String name = activity == null ? "" : activity.toLowerCase(Locale.ENGLISH);
        if (name.contains("battlestaff") || name.contains("battlestav") || name.contains("zaff"))
        {
            return Rule.BATTLESTAVES;
        }
        if (name.contains("herb box") || name.contains("nmz"))
        {
            return Rule.HERB_BOXES;
        }
        if (name.contains("essence") || name.contains("cromperty"))
        {
            return Rule.ESSENCE;
        }
        if (name.contains("rune") || name.contains("lundail"))
        {
            return Rule.RUNES;
        }
        if (name.contains("sand") || name.contains("bert"))
        {
            return Rule.SAND;
        }
        if (name.contains("flax") || name.contains("bowstring"))
        {
            return Rule.FLAX;
        }
        if (name.contains("arrow") || name.contains("rantz"))
        {
            return Rule.ARROWS;
        }
        if (name.contains("bonemeal") || name.contains("slime") || name.contains("robin"))
        {
            return Rule.BONEMEAL;
        }
        if (name.contains("dynamite") || name.contains("thirus"))
        {
            return Rule.DYNAMITE;
        }
        return Rule.MANUAL;
    }

    enum Status
    {
        READY,
        COMPLETE,
        UNAVAILABLE,
        UNKNOWN,
        MANUAL
    }

    private enum Rule
    {
        BATTLESTAVES,
        HERB_BOXES,
        ESSENCE,
        RUNES,
        SAND,
        FLAX,
        ARROWS,
        BONEMEAL,
        DYNAMITE,
        MANUAL
    }
}

package com.gielinorbriefing;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;

@Slf4j
@Singleton
class BankHistoryStore
{
    private static final int VERSION = 1;
    private static final long HOURLY_SECONDS = 3600;

    private final Gson gson;
    private final ConfigManager configManager;
    private final ItemManager itemManager;
    private final BankPortfolioStore portfolioStore;
    private final Path directory = RuneLite.RUNELITE_DIR.toPath().resolve("gielinor-dashboard");

    @Inject
    BankHistoryStore(Gson gson, ConfigManager configManager, ItemManager itemManager,
        BankPortfolioStore portfolioStore)
    {
        this.gson = gson;
        this.configManager = configManager;
        this.itemManager = itemManager;
        this.portfolioStore = portfolioStore;
    }

    synchronized BankHistory read()
    {
        Path path = profilePath();
        if (!Files.exists(path))
        {
            return BankHistory.empty();
        }
        try (Reader reader = Files.newBufferedReader(path, StandardCharsets.UTF_8))
        {
            StoredHistory stored = gson.fromJson(reader, StoredHistory.class);
            if (stored == null || stored.version != VERSION || stored.samples == null)
            {
                return BankHistory.empty();
            }
            return new BankHistory(stored.samples, stored.holdingsSyncedAt, stored.pricedItems,
                stored.totalItems);
        }
        catch (IOException | JsonSyntaxException ex)
        {
            log.warn("Unable to read bank history from {}", path, ex);
            return BankHistory.empty();
        }
    }

    synchronized BankHistory record(boolean force)
    {
        Map<Integer, Long> holdings = portfolioStore.load();
        if (holdings.isEmpty())
        {
            return read();
        }
        BankHistory current = read();
        long now = Instant.now().getEpochSecond();
        if (!force && !current.samples.isEmpty()
            && now - current.samples.get(current.samples.size() - 1).timestamp < HOURLY_SECONDS)
        {
            return current;
        }

        long total = 0;
        int priced = 0;
        for (Map.Entry<Integer, Long> item : holdings.entrySet())
        {
            int price = itemManager.getItemPrice(item.getKey());
            if (price <= 0)
            {
                continue;
            }
            priced++;
            total = saturatingAdd(total, saturatingMultiply(price, item.getValue()));
        }
        List<BankSample> samples = new ArrayList<>(current.samples);
        if (!samples.isEmpty() && now - samples.get(samples.size() - 1).timestamp < 60)
        {
            samples.set(samples.size() - 1, new BankSample(now, total));
        }
        else
        {
            samples.add(new BankSample(now, total));
        }
        BankHistory updated = new BankHistory(samples,
            force || current.holdingsSyncedAt == 0 ? now : current.holdingsSyncedAt,
            priced, holdings.size());
        write(updated);
        return updated;
    }

    synchronized void clear()
    {
        try
        {
            Files.deleteIfExists(profilePath());
        }
        catch (IOException ex)
        {
            log.warn("Unable to clear bank history", ex);
        }
    }

    private void write(BankHistory history)
    {
        try
        {
            Files.createDirectories(directory);
            Path target = profilePath();
            Path temporary = target.resolveSibling(target.getFileName() + ".tmp");
            try (Writer writer = Files.newBufferedWriter(temporary, StandardCharsets.UTF_8))
            {
                gson.toJson(new StoredHistory(VERSION, history.samples, history.holdingsSyncedAt,
                    history.pricedItems, history.totalItems), writer);
            }
            try
            {
                Files.move(temporary, target, StandardCopyOption.REPLACE_EXISTING,
                    StandardCopyOption.ATOMIC_MOVE);
            }
            catch (IOException ex)
            {
                Files.move(temporary, target, StandardCopyOption.REPLACE_EXISTING);
            }
        }
        catch (IOException ex)
        {
            log.warn("Unable to store bank history", ex);
        }
    }

    private Path profilePath()
    {
        String profile = configManager.getRSProfileKey();
        String safe = profile == null ? "logged-out" : Integer.toHexString(profile.hashCode());
        return directory.resolve("bank-" + safe + ".json");
    }

    private static long saturatingMultiply(long left, long right)
    {
        try
        {
            return Math.multiplyExact(left, right);
        }
        catch (ArithmeticException ex)
        {
            return Long.MAX_VALUE;
        }
    }

    private static long saturatingAdd(long left, long right)
    {
        try
        {
            return Math.addExact(left, right);
        }
        catch (ArithmeticException ex)
        {
            return Long.MAX_VALUE;
        }
    }

    @Value
    static class BankSample
    {
        long timestamp;
        long value;
    }

    @Value
    static class BankHistory
    {
        List<BankSample> samples;
        long holdingsSyncedAt;
        int pricedItems;
        int totalItems;

        static BankHistory empty()
        {
            return new BankHistory(Collections.emptyList(), 0, 0, 0);
        }
    }

    @Value
    private static class StoredHistory
    {
        int version;
        List<BankSample> samples;
        long holdingsSyncedAt;
        int pricedItems;
        int totalItems;
    }
}

