import java.awt.Component;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.plugins.timetracking.TimeablePanel;
import net.runelite.api.Skill;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.slayer.SlayerPlugin;
import net.runelite.client.plugins.slayer.SlayerPluginService;
import net.runelite.client.plugins.timetracking.SummaryState;
import net.runelite.client.plugins.timetracking.Tab;
import net.runelite.client.plugins.timetracking.TimeTrackingPlugin;
import net.runelite.client.plugins.timetracking.clocks.ClockManager;
import net.runelite.client.plugins.timetracking.farming.FarmingContractManager;
import net.runelite.client.plugins.timetracking.farming.FarmingTracker;
import net.runelite.client.plugins.timetracking.farming.FarmingTabPanel;
import net.runelite.client.plugins.timetracking.hunter.BirdHouseTracker;
import net.runelite.client.plugins.xptracker.XpTrackerPlugin;
import net.runelite.client.plugins.xptracker.XpTrackerService;
import net.runelite.client.util.Text;

@Singleton
class CorePluginBridge
{
    private final PluginManager pluginManager;
    private final GielinorBriefingConfig config;
    private final Map<Tab, FarmingTabPanel> farmingPanels = new EnumMap<>(Tab.class);
    private Plugin farmingPanelOwner;

    @Inject
    CorePluginBridge(PluginManager pluginManager, GielinorBriefingConfig config)
    {
        this.pluginManager = pluginManager;
        this.config = config;
    }

    List<String> slayerLines()
    {
        Plugin plugin = active(SlayerPlugin.class);
        if (plugin == null)
        {
            return unavailable("Enable RuneLite's Slayer plugin to synchronize tasks.");
        }
        SlayerPluginService service = plugin.getInjector().getInstance(SlayerPluginService.class);
        if (service.getTask() == null || service.getTask().isEmpty())
        {
            return unavailable("No active Slayer task is known.");
        }
        List<String> lines = new ArrayList<>();
        lines.add(service.getTask() + (service.getTaskLocation() == null ? ""
            : " — " + service.getTaskLocation()));
        int completed = Math.max(0, service.getInitialAmount() - service.getRemainingAmount());
        int percent = service.getInitialAmount() <= 0 ? 0
            : completed * 100 / service.getInitialAmount();
        lines.add(service.getRemainingAmount() + " / " + service.getInitialAmount()
            + " remaining | " + percent + "% complete");
        return lines;
    }

    String slayerTaskName()
    {
        Plugin plugin = active(SlayerPlugin.class);
        if (plugin == null)
        {
            return null;
        }
        SlayerPluginService service = plugin.getInjector().getInstance(SlayerPluginService.class);
        String task = service.getTask();
        return task == null || task.trim().isEmpty() ? null : task.trim();
    }

    List<String> farmingLines()
    {
        Plugin plugin = active(TimeTrackingPlugin.class);
        if (plugin == null)
        {
            return unavailable("Enable Time Tracking to synchronize farm runs.");
        }
        FarmingTracker tracker = plugin.getInjector().getInstance(FarmingTracker.class);
        FarmingContractManager contract = plugin.getInjector()
            .getInstance(FarmingContractManager.class);
        if (farmingPanelOwner != plugin)
        {
            farmingPanels.clear();
            farmingPanelOwner = plugin;
        }
        List<String> lines = new ArrayList<>();
        for (Tab tab : Tab.FARMING_TABS)
        {
            if (!farmTabEnabled(tab))
            {
                continue;
            }
            FarmingTabPanel panel = farmingPanels.computeIfAbsent(tab,
                ignored -> tracker.createTabPanel(tab, contract));
            panel.update();
            String category = tab.getName().replace(" Patches", "");
            for (Component component : panel.getComponents())
            {
                if (!(component instanceof TimeablePanel))
                {
                    continue;
                }
                TimeablePanel<?> patch = (TimeablePanel<?>) component;
                String status = clean(patch.getEstimate().getText());
                if (!config.farmUnknown() && "Unknown".equalsIgnoreCase(status))
                {
                    continue;
                }
                String location = clean(patch.getText().getText());
                String produce = clean(patch.getIcon().getToolTipText());
                StringBuilder line = new StringBuilder(category).append(" · ").append(location);
                if (produce != null && !produce.isEmpty())
                {
                    line.append(" · ").append(produce);
                }
                line.append(" · ").append(status == null || status.isEmpty() ? "Unknown" : status);
                lines.add(line.toString());
            }
        }
        return lines.isEmpty() ? unavailable(
            "No observed patches in the enabled Farm Runs categories.") : lines;
    }

    private boolean farmTabEnabled(Tab tab)
    {
        switch (tab)
        {
            case HERB: return config.farmHerbs();
            case TREE: return config.farmTrees();
            case FRUIT_TREE: return config.farmFruitTrees();
            case FLOWER: return config.farmFlowers();
            case HOPS: return config.farmHops();
            case BUSH: return config.farmBushes();
            case GRAPE: return config.farmGrapes();
            case ALLOTMENT: return config.farmAllotments();
            case SPECIAL: return config.farmSpecial();
            default: return false;
        }
    }

    private static String clean(String value)
    {
        return value == null ? null : Text.removeTags(value).replaceAll("\\s+", " ").trim();
    }

    List<String> birdHouseLines()
    {
        Plugin plugin = active(TimeTrackingPlugin.class);
        if (plugin == null)
        {
            return unavailable("Enable Time Tracking to synchronize bird houses.");
        }
        BirdHouseTracker tracker = plugin.getInjector().getInstance(BirdHouseTracker.class);
        List<String> lines = new ArrayList<>();
        lines.add("Run status: " + friendly(tracker.getSummary()));
        lines.add(tracker.getCompletionTime() < 0 ? "Visit Fossil Island to synchronize."
            : tracker.getCompletionTime() == 0 ? "Ready now"
            : "Ready" + completion(tracker.getCompletionTime()));
        return lines;
    }

    List<String> xpLines(Skill skill)
    {
        Plugin plugin = active(XpTrackerPlugin.class);
        if (plugin == null)
        {
            return unavailable("Enable XP Tracker for rates and goal estimates.");
        }
        XpTrackerService service = plugin.getInjector().getInstance(XpTrackerService.class);
        List<String> lines = new ArrayList<>();
        lines.add(skill.getName() + ": " + format(service.getXpHr(skill)) + " XP/hr");
        lines.add(format(service.getActions(skill)) + " actions this session");
        if (service.getActionsLeft(skill) > 0)
        {
            lines.add(format(service.getActionsLeft(skill)) + " actions to goal");
            lines.add("ETA " + service.getTimeTilGoal(skill));
        }
        return lines;
    }

    List<String> timerLines()
    {
        Plugin plugin = active(TimeTrackingPlugin.class);
        if (plugin == null)
        {
            return unavailable("Enable Time Tracking to show timers and cooldowns.");
        }
        ClockManager clocks = plugin.getInjector().getInstance(ClockManager.class);
        FarmingContractManager contract = plugin.getInjector()
            .getInstance(FarmingContractManager.class);
        List<String> lines = new ArrayList<>();
        lines.add(clocks.getActiveTimerCount() + " active timers");
        lines.add(clocks.getActiveStopwatchCount() + " active stopwatches");
        lines.add(contract.hasContract() ? "Contract: " + contract.getContractName()
            + " — " + friendly(contract.getSummary()) : "No Farming Guild contract tracked");
        return lines;
    }

    private Plugin active(Class<? extends Plugin> type)
    {
        for (Plugin plugin : pluginManager.getPlugins())
        {
            if (type.isInstance(plugin) && pluginManager.isPluginActive(plugin))
            {
                return plugin;
            }
        }
        return null;
    }

    private static List<String> unavailable(String message)
    {
        List<String> lines = new ArrayList<>();
        lines.add(message);
        return lines;
    }

    private static String friendly(SummaryState state)
    {
        return state.name().toLowerCase().replace('_', ' ');
    }

    private static String completion(long epochSeconds)
    {
        if (epochSeconds <= 0)
        {
            return epochSeconds == 0 ? " — ready" : "";
        }
        long seconds = Math.max(0, epochSeconds - System.currentTimeMillis() / 1000);
        return " — " + seconds / 3600 + "h " + seconds % 3600 / 60 + "m";
    }

    private static String format(int value)
    {
        return String.format("%,d", Math.max(0, value));
    }
}

package com.gielinorbriefing;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.StringJoiner;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.client.config.ConfigManager;

@Singleton
class BankPortfolioStore
{
    private static final String KEY = "bankSnapshot";

    private final ConfigManager configManager;

    @Inject
    BankPortfolioStore(ConfigManager configManager)
    {
        this.configManager = configManager;
    }

    void capture(ItemContainer bank)
    {
        Map<Integer, Long> quantities = new HashMap<>();
        for (Item item : bank.getItems())
        {
            if (item.getId() > 0 && item.getQuantity() > 0)
            {
                quantities.merge(item.getId(), (long) item.getQuantity(), Long::sum);
            }
        }

        StringJoiner encoded = new StringJoiner(",");
        quantities.entrySet().stream()
            .sorted(Map.Entry.comparingByKey())
            .forEach(entry -> encoded.add(entry.getKey() + ":" + entry.getValue()));
        configManager.setRSProfileConfiguration(GielinorBriefingConfig.GROUP, KEY,
            encoded.toString());
    }

    Map<Integer, Long> load()
    {
        String encoded = configManager.getRSProfileConfiguration(GielinorBriefingConfig.GROUP, KEY);
        if (encoded == null || encoded.isEmpty())
        {
            return Collections.emptyMap();
        }

        Map<Integer, Long> quantities = new HashMap<>();
        for (String entry : encoded.split(","))
        {
            String[] parts = entry.split(":", 2);
            if (parts.length != 2)
            {
                continue;
            }
            try
            {
                int itemId = Integer.parseInt(parts[0]);
                long quantity = Long.parseLong(parts[1]);
                if (itemId > 0 && quantity > 0)
                {
                    quantities.put(itemId, quantity);
                }
            }
            catch (NumberFormatException ignored)
            {
                // Ignore one malformed entry without discarding the remaining bank snapshot.
            }
        }
        return Collections.unmodifiableMap(quantities);
    }
}

