package com.gielinorbriefing;

import java.time.LocalDate;
import java.time.temporal.WeekFields;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

@Singleton
class DailyChecklistStore
{
    private static final String KEY = "dailyChecklist";
    private final ConfigManager configManager;
    private final GielinorBriefingConfig config;

    @Inject
    DailyChecklistStore(ConfigManager configManager, GielinorBriefingConfig config)
    {
        this.configManager = configManager;
        this.config = config;
    }

    List<Entry> entries()
    {
        Map<String, String> completed = load();
        List<Entry> result = new ArrayList<>();
        for (String configured : config.dailyActivities().split(","))
        {
            String name = configured.trim();
            if (name.isEmpty())
            {
                continue;
            }
            String period = period(name);
            result.add(new Entry(name, period.equals(completed.get(id(name)))));
        }
        return result;
    }

    void toggle(int index)
    {
        List<Entry> entries = entries();
        if (index < 0 || index >= entries.size())
        {
            return;
        }
        Entry entry = entries.get(index);
        Map<String, String> completed = load();
        String key = id(entry.name);
        if (entry.complete)
        {
            completed.remove(key);
        }
        else
        {
            completed.put(key, period(entry.name));
        }
        String encoded = completed.entrySet().stream()
            .map(value -> value.getKey() + ":" + value.getValue())
            .collect(Collectors.joining(","));
        configManager.setRSProfileConfiguration(GielinorBriefingConfig.GROUP, KEY, encoded);
    }

    private Map<String, String> load()
    {
        String encoded = configManager.getRSProfileConfiguration(GielinorBriefingConfig.GROUP, KEY);
        Map<String, String> result = new HashMap<>();
        if (encoded == null)
        {
            return result;
        }
        for (String token : encoded.split(","))
        {
            String[] parts = token.split(":", 2);
            if (parts.length == 2)
            {
                result.put(parts[0], parts[1]);
            }
        }
        return result;
    }

    private static String id(String name)
    {
        return Integer.toHexString(name.toLowerCase(Locale.ENGLISH).hashCode());
    }

    private static String period(String name)
    {
        LocalDate today = LocalDate.now();
        if (name.toLowerCase(Locale.ENGLISH).contains("tears"))
        {
            WeekFields weeks = WeekFields.ISO;
            return today.getYear() + "w" + today.get(weeks.weekOfWeekBasedYear());
        }
        return today.toString();
    }

    static final class Entry
    {
        private final String name;
        private final boolean complete;

        Entry(String name, boolean complete)
        {
            this.name = name;
            this.complete = complete;
        }

        String getName()
        {
            return name;
        }

        boolean isComplete()
        {
            return complete;
        }
    }
}

package com.gielinorbriefing;

import java.time.Duration;
import java.time.Instant;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
class BriefingService
{
    private final NewsClient newsClient;
    private final MarketClient marketClient;
    private final GielinorBriefingConfig config;
    private final BankPortfolioStore bankPortfolioStore;
    private final MarketHistoryStore marketHistoryStore;
    private final ScheduledExecutorService executor;
    private final AtomicReference<BriefingSnapshot> snapshot =
        new AtomicReference<>(BriefingSnapshot.EMPTY);
    private final AtomicBoolean refreshing = new AtomicBoolean();

    private volatile boolean running;
    private volatile Instant lastAttempt = Instant.EPOCH;
    private ScheduledFuture<?> pollTask;

    @Inject
    BriefingService(
        NewsClient newsClient,
        MarketClient marketClient,
        GielinorBriefingConfig config,
        BankPortfolioStore bankPortfolioStore,
        MarketHistoryStore marketHistoryStore,
        ScheduledExecutorService executor)
    {
        this.newsClient = newsClient;
        this.marketClient = marketClient;
        this.config = config;
        this.bankPortfolioStore = bankPortfolioStore;
        this.marketHistoryStore = marketHistoryStore;
        this.executor = executor;
    }

    void start()
    {
        running = true;
        pollTask = executor.scheduleWithFixedDelay(this::refreshIfDue, 0, 1, TimeUnit.MINUTES);
    }

    void stop()
    {
        running = false;
        if (pollTask != null)
        {
            pollTask.cancel(false);
            pollTask = null;
        }
    }

    BriefingSnapshot getSnapshot()
    {
        return snapshot.get();
    }

    void refreshSoon()
    {
        lastAttempt = Instant.EPOCH;
        if (running)
        {
            executor.execute(this::refreshIfDue);
        }
    }

    private void refreshIfDue()
    {
        if (!running || Duration.between(lastAttempt, Instant.now()).toMinutes() < config.refreshMinutes()
            || !refreshing.compareAndSet(false, true))
        {
            return;
        }

        lastAttempt = Instant.now();
        BriefingSnapshot before = snapshot.get();
        snapshot.set(new BriefingSnapshot(before.getNews(), before.getGainers(), before.getLosers(),
            before.getBankMovers(), before.getMarketPulse(), before.getWatchlist(),
            before.getUpdatedAt(), true));

        List<NewsItem> news = before.getNews();
        List<MarketMover> gainers = before.getGainers();
        List<MarketMover> losers = before.getLosers();
        List<BankMover> bankMovers = before.getBankMovers();
        MarketPulse marketPulse = before.getMarketPulse();
        List<WatchlistItem> watchlist = before.getWatchlist();
        boolean updated = false;

        try
        {
            news = newsClient.fetch();
            updated = true;
        }
        catch (Exception ex)
        {
            log.warn("Unable to refresh OSRS news", ex);
        }

        try
        {
            MarketClient.MoverLists movers = marketClient.fetchMovers(
                config.minimumPercent(), config.minimumGpChange(), config.minimumDailyVolume(),
                config.minimumValuableItemPrice(), config.minimumValuableSwing(),
                config.minimumValuableVolume(), config.marketMoverCount(),
                bankPortfolioStore.load(), 6,
                config.watchlist());
            gainers = movers.getGainers();
            losers = movers.getLosers();
            bankMovers = movers.getBankMovers();
            marketPulse = movers.getMarketPulse();
            if (marketPulse.getSampleSize() > 0)
            {
                marketPulse = marketPulse.withHistory(
                    marketHistoryStore.record(marketPulse.getIndexChange(), Instant.now()));
            }
            watchlist = movers.getWatchlist();
            updated = true;
        }
        catch (Exception ex)
        {
            log.warn("Unable to refresh GE movers", ex);
        }
        finally
        {
            if (running)
            {
                snapshot.set(new BriefingSnapshot(news, gainers, losers, bankMovers,
                    marketPulse, watchlist,
                    updated ? Instant.now() : before.getUpdatedAt(), false));
            }
            refreshing.set(false);
        }
    }
}

