package com.gielinorbriefing;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;

@Singleton
class SessionLootStore
{
    private final ItemManager itemManager;
    private final Deque<LootLine> recent = new ArrayDeque<>();
    private long totalValue;

    @Inject
    SessionLootStore(ItemManager itemManager)
    {
        this.itemManager = itemManager;
    }

    synchronized void add(String source, java.util.Collection<ItemStack> items)
    {
        for (ItemStack item : items)
        {
            int price = itemManager.getItemPrice(item.getId());
            long value = Math.max(0L, (long) price * item.getQuantity());
            totalValue += value;
            String name = itemManager.getItemComposition(item.getId()).getName();
            recent.addFirst(new LootLine(source, item.getId(), name, item.getQuantity(), value));
        }
        while (recent.size() > 30)
        {
            recent.removeLast();
        }
    }

    synchronized Snapshot snapshot()
    {
        return new Snapshot(totalValue,
            Collections.unmodifiableList(new ArrayList<>(recent)));
    }

    @Value
    static class LootLine
    {
        String source;
        int itemId;
        String item;
        int quantity;
        long value;
    }

    @Value
    static class Snapshot
    {
        long totalValue;
        List<LootLine> recent;
    }
}

