@Singleton
class DashboardDataService
{
    private static final DateTimeFormatter TIME = DateTimeFormatter.ofPattern("MMM d, h:mm a")
        .withZone(ZoneId.systemDefault());

    private final Client client;
    private final ItemManager itemManager;
    private final BriefingService briefingService;
    private final CorePluginBridge bridge;
    private final BankHistoryStore bankHistoryStore;
    private final BankPortfolioStore bankPortfolioStore;
    private final SessionLootStore lootStore;
    private final DailyChecklistStore dailyStore;
    private final DailyTaskTracker dailyTaskTracker;
    private final SlayerImageService slayerImageService;
    private final GielinorBriefingConfig config;

    private volatile DashboardSnapshot cached = DashboardSnapshot.empty();
    private volatile long cachedAt;

    @Inject
    DashboardDataService(Client client, ItemManager itemManager, BriefingService briefingService,
        CorePluginBridge bridge, BankHistoryStore bankHistoryStore,
        BankPortfolioStore bankPortfolioStore, SessionLootStore lootStore,
        DailyChecklistStore dailyStore, DailyTaskTracker dailyTaskTracker,
        SlayerImageService slayerImageService,
        GielinorBriefingConfig config)
    {
        this.client = client;
        this.itemManager = itemManager;
        this.briefingService = briefingService;
        this.bridge = bridge;
        this.bankHistoryStore = bankHistoryStore;
        this.bankPortfolioStore = bankPortfolioStore;
        this.lootStore = lootStore;
        this.dailyStore = dailyStore;
        this.dailyTaskTracker = dailyTaskTracker;
        this.slayerImageService = slayerImageService;
        this.config = config;
    }

    DashboardSnapshot snapshot()
    {
        long now = System.currentTimeMillis();
        if (now - cachedAt < 1000)
        {
            return cached;
        }
        synchronized (this)
        {
            if (now - cachedAt < 1000)
            {
                return cached;
            }
            cached = build();
            cachedAt = now;
            return cached;
        }
    }

    void bankSynchronized()
    {
        bankHistoryStore.record(true);
        invalidate();
    }

    void recordHourlyBankValue()
    {
        bankHistoryStore.record(false);
        invalidate();
    }

    void invalidate()
    {
        cachedAt = 0;
    }

    void refreshBriefing()
    {
        briefingService.refreshSoon();
        invalidate();
    }

    void toggleDaily(int index)
    {
        List<DailyChecklistStore.Entry> entries = dailyStore.entries();
        if (index < 0 || index >= entries.size()
            || dailyTaskTracker.isAutoTracked(entries.get(index).getName()))
        {
            return;
        }
        dailyStore.toggle(index);
        invalidate();
    }

    void openNews(int index)
    {
        List<NewsItem> news = briefingService.getSnapshot().getNews();
        if (index >= 0 && index < news.size() && news.get(index).getLink() != null)
        {
            LinkBrowser.browse(news.get(index).getLink());
        }
    }

    void openSlayerWiki()
    {
        LinkBrowser.browse(slayerImageService.getWikiUrl());
    }

    private DashboardSnapshot build()
    {
        BriefingSnapshot briefing = briefingService.getSnapshot();
        BankHistoryStore.BankHistory storedBankHistory = bankHistoryStore.read();
        Map<Integer, Long> bankHoldings = bankPortfolioStore.load();
        boolean demoBankHistory = storedBankHistory.getSamples().isEmpty()
            && config.demoBankHistory();
        BankHistoryStore.BankHistory bankHistory = demoBankHistory
            ? demoBankHistory(Instant.now().getEpochSecond()) : storedBankHistory;
        Map<DashboardWidgetType, List<String>> widgets =
            new EnumMap<>(DashboardWidgetType.class);
        Map<DashboardWidgetType, List<Integer>> itemIds =
            new EnumMap<>(DashboardWidgetType.class);

        widgets.put(DashboardWidgetType.BANK_HISTORY,
            bankHistoryLines(bankHistory, demoBankHistory, bankHoldings));
        widgets.put(DashboardWidgetType.BANK_MOVERS, bankMoverLines(briefing));
        widgets.put(DashboardWidgetType.GE_MARKET, marketLines(briefing));
        widgets.put(DashboardWidgetType.GE_OFFERS, offerLines());
        widgets.put(DashboardWidgetType.NEWS, newsLines(briefing));
        widgets.put(DashboardWidgetType.SLAYER, slayerLines());
        widgets.put(DashboardWidgetType.FARM_RUNS, bridge.farmingLines());
        widgets.put(DashboardWidgetType.BIRD_HOUSES, bridge.birdHouseLines());
        widgets.put(DashboardWidgetType.XP_GOALS, xpLines());
        widgets.put(DashboardWidgetType.RECENT_LOOT, lootLines());
        widgets.put(DashboardWidgetType.BOSS_PROGRESS, bossLines());
        widgets.put(DashboardWidgetType.QUEST_DIARY, questLines());
        widgets.put(DashboardWidgetType.COLLECTION_CLUES, collectionLines());
        widgets.put(DashboardWidgetType.TIMERS, bridge.timerLines());
        widgets.put(DashboardWidgetType.DAILIES, dailyLines());

        itemIds.put(DashboardWidgetType.BANK_MOVERS, snapshotBankMoverIds(briefing));
        itemIds.put(DashboardWidgetType.BANK_HISTORY,
            bankHistoryItemIds(bankHistory, demoBankHistory, bankHoldings));
        itemIds.put(DashboardWidgetType.GE_MARKET, snapshotMarketIds(briefing));
        itemIds.put(DashboardWidgetType.GE_OFFERS, offerItemIds());
        itemIds.put(DashboardWidgetType.RECENT_LOOT, lootItemIds());
        itemIds.put(DashboardWidgetType.SLAYER, slayerItemIds());

        return new DashboardSnapshot(Collections.unmodifiableMap(widgets),
            Collections.unmodifiableMap(itemIds), bankHistory,
            briefing.getUpdatedAt(), briefing.isLoading());
    }

    private List<String> slayerLines()
    {
        List<String> lines = new ArrayList<>(bridge.slayerLines());
        if (bridge.slayerTaskName() == null)
        {
            return lines;
        }
        List<SlayerImageService.Detail> details = slayerImageService.getDetails();
        if (details.isEmpty())
        {
            lines.add("Monster gear and drops are loading...");
        }
        else
        {
            for (SlayerImageService.Detail detail : details)
            {
                lines.add(detail.getText());
            }
        }
        return lines;
    }

    private List<Integer> slayerItemIds()
    {
        List<Integer> result = new ArrayList<>();
        result.add(0);
        result.add(0);
        for (SlayerImageService.Detail detail : slayerImageService.getDetails())
        {
            result.add(detail.getItemId());
        }
        return result;
    }

    private List<String> bankHistoryLines(BankHistoryStore.BankHistory history, boolean demo,
        Map<Integer, Long> holdings)
    {
        if (history.getSamples().isEmpty())
        {
            return lines("Open your bank to begin local value history.",
                "Holdings never leave this computer.");
        }
        BankHistoryStore.BankSample latest = history.getSamples()
            .get(history.getSamples().size() - 1);
        long first = history.getSamples().get(0).getValue();
        long change = latest.getValue() - first;
        int coverage = history.getTotalItems() == 0 ? 0
            : history.getPricedItems() * 100 / history.getTotalItems();
        if (demo)
        {
            return lines(formatGp(latest.getValue()) + " demo bank value",
                signedGp(change) + " across the demo period",
                "DEMO DATA · open your bank to replace it",
                history.getSamples().size() + " simulated daily samples");
        }
        long coins = holdings.getOrDefault(ItemID.COINS, 0L);
        long platinum = holdings.getOrDefault(ItemID.PLATINUM, 0L);
        long platinumGp = saturatingMultiply(platinum, 1_000L);
        long liquidTotal = liquidTotal(coins, platinum);
        List<String> result = new ArrayList<>();
        result.add(formatGp(latest.getValue()) + " total value");
        result.add("Cash stack " + formatGp(coins) + " GP");
        if (platinum > 0)
        {
            result.add("Platinum " + String.format("%,d", platinum) + " tokens = "
                + formatGp(platinumGp) + " GP");
        }
        result.add("Liquid total " + formatGp(liquidTotal) + " GP");
        result.add(signedGp(change) + " since tracking began · " + coverage + "% priced");
        return result;
    }

    private static List<Integer> bankHistoryItemIds(BankHistoryStore.BankHistory history,
        boolean demo, Map<Integer, Long> holdings)
    {
        if (demo || history.getSamples().isEmpty())
        {
            return Collections.emptyList();
        }
        List<Integer> result = new ArrayList<>();
        result.add(0);
        result.add(ItemID.COINS);
        if (holdings.getOrDefault(ItemID.PLATINUM, 0L) > 0)
        {
            result.add(ItemID.PLATINUM);
        }
        result.add(0);
        return result;
    }

    private static long saturatingMultiply(long left, long right)
    {
        try
        {
            return Math.multiplyExact(left, right);
        }
        catch (ArithmeticException ignored)
        {
            return Long.MAX_VALUE;
        }
    }

    static long liquidTotal(long coins, long platinumTokens)
    {
        return saturatingAdd(coins, saturatingMultiply(platinumTokens, 1_000L));
    }

    private static long saturatingAdd(long left, long right)
    {
        try
        {
            return Math.addExact(left, right);
        }
        catch (ArithmeticException ignored)
        {
            return Long.MAX_VALUE;
        }
    }

    static BankHistoryStore.BankHistory demoBankHistory(long now)
    {
        long day = 86_400L;
        long[] values = {
            382_200_000L, 385_900_000L, 381_700_000L, 389_400_000L, 393_100_000L,
            391_600_000L, 398_800_000L, 404_200_000L, 401_500_000L, 409_700_000L,
            407_900_000L, 415_400_000L, 419_800_000L, 417_200_000L, 423_600_000L,
            421_100_000L, 426_900_000L, 432_400_000L, 429_800_000L, 435_100_000L,
            428_600_000L
        };
        List<BankHistoryStore.BankSample> samples = new ArrayList<>();
        long start = now - (values.length - 1L) * day;
        for (int index = 0; index < values.length; index++)
        {
            samples.add(new BankHistoryStore.BankSample(start + index * day, values[index]));
        }
        return new BankHistoryStore.BankHistory(Collections.unmodifiableList(samples), now,
            742, 748);
    }

    private List<String> bankMoverLines(BriefingSnapshot snapshot)
    {
        if (snapshot.getBankMovers().isEmpty())
        {
            return lines("Open your bank and wait for a market refresh.");
        }
        List<String> lines = new ArrayList<>();
        for (BankMover mover : snapshot.getBankMovers())
        {
            lines.add(mover.getName() + "  " + signedGp(mover.getTotalGpChange())
                + "  " + String.format("%+.1f%%", mover.getPercentChange()));
        }
        return lines;
    }

    private List<String> marketLines(BriefingSnapshot snapshot)
    {
        List<String> lines = new ArrayList<>();
        List<MarketMover> movers = rankedMarketMovers(snapshot, config.marketMoverCount());
        for (MarketMover mover : movers)
        {
            lines.add((mover.getGpChange() > 0 ? "↑ " : "↓ ") + mover.getName() + "  "
                + formatGp(mover.getCurrentPrice()) + "  " + signedGp(mover.getGpChange())
                + " (" + String.format("%+.1f%%", mover.getPercentChange()) + ")");
        }
        return lines.isEmpty() ? lines("No valuable item swings match your filters.") : lines;
    }

    static List<MarketMover> rankedMarketMovers(BriefingSnapshot snapshot, int limit)
    {
        List<MarketMover> movers = new ArrayList<>(snapshot.getGainers());
        movers.addAll(snapshot.getLosers());
        movers.sort(Comparator
            .comparingLong((MarketMover mover) -> safeAbs(mover.getGpChange())).reversed()
            .thenComparing(Comparator.comparingDouble(
                (MarketMover mover) -> Math.abs(mover.getPercentChange())).reversed()));
        return new ArrayList<>(movers.subList(0, Math.min(Math.max(0, limit), movers.size())));
    }

    private static boolean containsMover(List<MarketMover> movers, int itemId)
    {
        for (MarketMover mover : movers)
        {
            if (mover.getItemId() == itemId)
            {
                return true;
            }
        }
        return false;
    }

    private List<String> offerLines()
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return lines("Log in to view Grand Exchange offers.");
        }
        List<String> lines = new ArrayList<>();
        GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
        for (int i = 0; i < offers.length; i++)
        {
            GrandExchangeOffer offer = offers[i];
            if (offer.getState() == GrandExchangeOfferState.EMPTY)
            {
                continue;
            }
            String name = itemManager.getItemComposition(offer.getItemId()).getName();
            int percent = offer.getTotalQuantity() == 0 ? 0
                : offer.getQuantitySold() * 100 / offer.getTotalQuantity();
            lines.add("Slot " + (i + 1) + " · " + name + " · " + percent + "% · "
                + formatGp(offer.getPrice()) + " ea");
        }
        return lines.isEmpty() ? lines("No active Grand Exchange offers.") : lines;
    }

    private List<Integer> offerItemIds()
    {
        List<Integer> result = new ArrayList<>();
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return result;
        }
        for (GrandExchangeOffer offer : client.getGrandExchangeOffers())
        {
            if (offer.getState() != GrandExchangeOfferState.EMPTY)
            {
                result.add(offer.getItemId());
            }
        }
        return result;
    }

    private List<String> newsLines(BriefingSnapshot snapshot)
    {
        if (snapshot.getNews().isEmpty())
        {
            return lines("Official Old School news is loading…");
        }
        List<String> lines = new ArrayList<>();
        for (NewsItem item : snapshot.getNews())
        {
            lines.add(item.getTitle() + (item.getPublishedAt() == null ? ""
                : " · " + TIME.format(item.getPublishedAt())));
            if (lines.size() == 5)
            {
                break;
            }
        }
        return lines;
    }

    private List<String> xpLines()
    {
        Skill skill = config.pinnedSkill();
        List<String> lines = new ArrayList<>();
        lines.add(skill.getName() + " level " + client.getRealSkillLevel(skill)
            + " · " + format(client.getSkillExperience(skill)) + " XP");
        lines.addAll(bridge.xpLines(skill));
        return lines;
    }

    private List<String> lootLines()
    {
        SessionLootStore.Snapshot loot = lootStore.snapshot();
        List<String> lines = new ArrayList<>();
        lines.add("Session total " + formatGp(loot.getTotalValue()));
        for (SessionLootStore.LootLine item : loot.getRecent())
        {
            lines.add(item.getItem() + " ×" + item.getQuantity() + " · "
                + formatGp(item.getValue()) + " · " + item.getSource());
            if (lines.size() == 6)
            {
                break;
            }
        }
        if (loot.getRecent().isEmpty())
        {
            lines.add("Loot received this session will appear here.");
        }
        return lines;
    }

    private List<Integer> lootItemIds()
    {
        List<Integer> result = new ArrayList<>();
        result.add(0); // Session total line.
        for (SessionLootStore.LootLine item : lootStore.snapshot().getRecent())
        {
            result.add(item.getItemId());
            if (result.size() == 6)
            {
                break;
            }
        }
        return result;
    }

    private static List<Integer> snapshotBankMoverIds(BriefingSnapshot snapshot)
    {
        List<Integer> result = new ArrayList<>();
        for (BankMover mover : snapshot.getBankMovers())
        {
            result.add(mover.getItemId());
        }
        return result;
    }

    private static List<Integer> snapshotMarketIds(BriefingSnapshot snapshot)
    {
        List<Integer> result = new ArrayList<>();
        List<MarketMover> movers = rankedMarketMovers(snapshot, Integer.MAX_VALUE);
        for (MarketMover mover : movers)
        {
            result.add(mover.getItemId());
        }
        return result;
    }

    private static long safeAbs(long value)
    {
        return value == Long.MIN_VALUE ? Long.MAX_VALUE : Math.abs(value);
    }

    private List<String> bossLines()
    {
        List<String> lines = new ArrayList<>();
        lines.add("Pinned activities");
        for (String boss : config.favoriteBosses().split(","))
        {
            if (!boss.trim().isEmpty())
            {
                lines.add("• " + boss.trim());
            }
        }
        lines.add("KC and PB values appear after RuneLite observes them.");
        return lines;
    }

    private List<String> questLines()
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return lines("Log in to synchronize quest progress.");
        }
        int finished = 0;
        int inProgress = 0;
        int notStarted = 0;
        for (Quest quest : Quest.values())
        {
            QuestState state = quest.getState(client);
            if (state == QuestState.FINISHED)
            {
                finished++;
            }
            else if (state == QuestState.IN_PROGRESS)
            {
                inProgress++;
            }
            else
            {
                notStarted++;
            }
        }
        return lines(finished + " quests complete", inProgress + " in progress",
            notStarted + " not started", "Diary tiers synchronize from game state.");
    }

    private List<String> collectionLines()
    {
        int clues = client.getGameState() == GameState.LOGGED_IN
            ? client.getVarpValue(VarPlayerID.COMPLETED_CLUES_TOTAL) : 0;
        return lines(format(clues) + " clues completed",
            "Open the Collection Log to synchronize unlocks.",
            "Clue totals synchronize when RuneLite observes the counters.",
            "Recent unlocks are retained per account.");
    }

    private List<String> dailyLines()
    {
        List<String> lines = new ArrayList<>();
        lines.add("Recurring checklist");
        for (DailyChecklistStore.Entry item : dailyStore.entries())
        {
            lines.add(formatDaily(item));
            if (lines.size() == 6)
            {
                break;
            }
        }
        return lines;
    }

    private String formatDaily(DailyChecklistStore.Entry item)
    {
        switch (dailyTaskTracker.status(item.getName()))
        {
            case READY:
                return "○ " + item.getName() + " · Ready";
            case COMPLETE:
                return "✓ " + item.getName() + " · Collected";
            case UNAVAILABLE:
                return "– " + item.getName() + " · Locked";
            case UNKNOWN:
                return "? " + item.getName() + " · Log in to check";
            default:
                return (item.isComplete() ? "✓ " : "○ ") + item.getName() + " · Manual";
        }
    }

    private static List<String> lines(String... values)
    {
        List<String> result = new ArrayList<>();
        Collections.addAll(result, values);
        return result;
    }

    static String formatGp(long value)
    {
        long absolute = Math.abs(value);
        if (absolute >= 1_000_000_000L)
        {
            return String.format("%.2fb", value / 1_000_000_000.0);
        }
        if (absolute >= 1_000_000L)
        {
            return String.format("%.1fm", value / 1_000_000.0);
        }
        if (absolute >= 1_000L)
        {
            return String.format("%.1fk", value / 1_000.0);
        }
        return Long.toString(value);
    }

    private static String signedGp(long value)
    {
        return (value >= 0 ? "+" : "") + formatGp(value);
    }

    private static String format(int value)
    {
        return String.format("%,d", value);
    }
}

package com.gielinorbriefing;

import java.awt.BasicStroke;
import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

@Singleton
class GielinorDashboardOverlay extends Overlay
{
    private static final int CARD_HEIGHT = 260;
    private static final int GAP = 12;
    private static final int GE_ITEMS_PER_PAGE = 4;
    private static final int RECOMMENDATION_ROWS_PER_PAGE = 3;
    private static final DateTimeFormatter UPDATED = DateTimeFormatter.ofPattern("h:mm a")
        .withZone(ZoneId.systemDefault());

    private final Client client;
    private final ItemManager itemManager;
    private final SlayerImageService slayerImageService;
    private final DashboardDataService dataService;
    private final DashboardLayoutStore layoutStore;
    private final GielinorBriefingConfig config;
    private final Map<DashboardWidgetType, Rectangle> cardBounds =
        new EnumMap<>(DashboardWidgetType.class);

    private DashboardLayoutStore.Layout layout;
    private boolean open;
    private boolean editing;
    private DashboardWidgetType draggingWidget;
    private DashboardWidgetType dragTargetWidget;
    private boolean dragTargetAfter;
    private int farmPage;
    private int farmPageCount = 1;
    private int gePage;
    private int gePageCount = 1;
    private int slayerView;
    private int slayerRecommendationPage;
    private int scroll;
    private Rectangle panelBounds = new Rectangle();
    private Rectangle closeBounds = new Rectangle();
    private Rectangle editBounds = new Rectangle();
    private Rectangle bossButtonBounds = new Rectangle();
    private Rectangle wikiButtonBounds = new Rectangle();

    @Inject
    GielinorDashboardOverlay(Client client, ItemManager itemManager,
        SlayerImageService slayerImageService,
        DashboardDataService dataService,
        DashboardLayoutStore layoutStore, GielinorBriefingConfig config)
    {
        this.client = client;
        this.itemManager = itemManager;
        this.slayerImageService = slayerImageService;
        this.dataService = dataService;
        this.layoutStore = layoutStore;
        this.config = config;
        this.layout = layoutStore.load();
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ALWAYS_ON_TOP);
        setMovable(false);
        setSnappable(false);
        setResettable(false);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            clearBounds();
            return null;
        }
        if (!open)
        {
            panelBounds = new Rectangle();
            cardBounds.clear();
            return null;
        }
        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
            RenderingHints.VALUE_ANTIALIAS_ON);
        graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
            RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        drawDashboard(graphics, dataService.snapshot());
        return new Dimension(client.getCanvasWidth(), client.getCanvasHeight());
    }

    private void drawDashboard(Graphics2D g, DashboardSnapshot snapshot)
    {
        int width = Math.max(560, client.getCanvasWidth() * config.dashboardScale() / 100);
        int height = Math.max(390, client.getCanvasHeight() * config.dashboardScale() / 100);
        width = Math.min(width, client.getCanvasWidth() - 24);
        height = Math.min(height, client.getCanvasHeight() - 24);
        int x = (client.getCanvasWidth() - width) / 2;
        int y = (client.getCanvasHeight() - height) / 2;
        panelBounds = new Rectangle(x, y, width, height);

        int alpha = config.dashboardOpacity() * 255 / 100;
        g.setColor(new Color(0, 0, 0, Math.min(230, alpha)));
        g.fillRoundRect(x + 5, y + 6, width, height, 12, 12);
        g.setColor(alpha(theme().background(), alpha));
        g.fillRoundRect(x, y, width, height, 12, 12);
        g.setColor(theme().border());
        g.setStroke(new BasicStroke(2f));
        g.drawRoundRect(x, y, width, height, 12, 12);

        drawHeader(g, snapshot, x, y, width);
        Rectangle viewport = new Rectangle(x + 14, y + 56, width - 28, height - 70);
        Graphics2D content = (Graphics2D) g.create();
        content.clip(viewport);
        List<DashboardWidgetType> widgets = displayedWidgets();
        int responsiveMaximum = viewport.width >= 510 ? 3 : viewport.width >= 340 ? 2 : 1;
        int columns = Math.min(config.dashboardColumns(), responsiveMaximum);
        int contentHeight = layoutCards(widgets, viewport, columns);
        int maxScroll = Math.max(0, contentHeight - viewport.height);
        scroll = Math.max(0, Math.min(scroll, maxScroll));
        cardBounds.replaceAll((type, bounds) -> new Rectangle(bounds.x, bounds.y - scroll,
            bounds.width, bounds.height));
        bossButtonBounds = new Rectangle();
        wikiButtonBounds = new Rectangle();
        for (DashboardWidgetType type : widgets)
        {
            drawCard(content, snapshot, type, cardBounds.get(type), layout.isVisible(type));
        }
        content.dispose();

        if (maxScroll > 0)
        {
            int trackHeight = viewport.height;
            int thumbHeight = Math.max(28, trackHeight * viewport.height / contentHeight);
            int thumbY = viewport.y + scroll * (trackHeight - thumbHeight) / maxScroll;
            g.setColor(new Color(255, 255, 255, 35));
            g.fillRoundRect(viewport.x + viewport.width - 5, viewport.y, 4, trackHeight, 4, 4);
            g.setColor(alpha(theme().primary(), 125));
            g.fillRoundRect(viewport.x + viewport.width - 5, thumbY, 4, thumbHeight, 4, 4);
        }
    }

    private void drawHeader(Graphics2D g, DashboardSnapshot snapshot, int x, int y, int width)
    {
        g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 21));
        g.setColor(theme().primary());
        String playerName = client.getLocalPlayer() == null
            || client.getLocalPlayer().getName() == null
                ? "BETTER DASHBOARD" : client.getLocalPlayer().getName();
        g.drawString(playerName, x + 18, y + 33);

        closeBounds = new Rectangle(x + width - 43, y + 12, 28, 28);
        editBounds = new Rectangle(x + width - 112, y + 12, 60, 28);
        drawControl(g, editBounds, editing ? "Done" : "Edit");
        drawControl(g, closeBounds, "×");

        String status = editing
            ? "Drag cards to reorder | Click show/hide | Right-click resize"
            : snapshot.isLoading() ? "Refreshing…"
            : snapshot.getUpdatedAt() == null ? "Waiting for data"
            : "Updated " + UPDATED.format(snapshot.getUpdatedAt());
        g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 11));
        g.setColor(theme().muted());
        FontMetrics fm = g.getFontMetrics();
        int right = editBounds.x - 12;
        status = ellipsize(status, fm, Math.max(80, right - (x + 245)));
        g.drawString(status, right - fm.stringWidth(status), y + 31);
    }

    private void drawControl(Graphics2D g, Rectangle bounds, String label)
    {
        g.setColor(new Color(255, 255, 255, 18));
        g.fillRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, 7, 7);
        g.setColor(theme().border());
        g.drawRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, 7, 7);
        g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 12));
        FontMetrics fm = g.getFontMetrics();
        g.setColor(theme().primary());
        g.drawString(label, bounds.x + (bounds.width - fm.stringWidth(label)) / 2,
            bounds.y + 19);
    }

    private int layoutCards(List<DashboardWidgetType> widgets, Rectangle viewport, int columns)
    {
        cardBounds.clear();
        int columnWidth = (viewport.width - GAP * (columns - 1)) / columns;
        int row = 0;
        int column = 0;
        for (DashboardWidgetType type : widgets)
        {
            int span = Math.min(columns, layout.span(type));
            if (column + span > columns)
            {
                row++;
                column = 0;
            }
            int cardWidth = columnWidth * span + GAP * (span - 1);
            int cardX = viewport.x + column * (columnWidth + GAP);
            int cardY = viewport.y + row * (CARD_HEIGHT + GAP);
            cardBounds.put(type, new Rectangle(cardX, cardY, cardWidth, CARD_HEIGHT));
            column += span;
            if (column >= columns)
            {
                row++;
                column = 0;
            }
        }
        if (column > 0)
        {
            row++;
        }
        return Math.max(0, row * (CARD_HEIGHT + GAP) - GAP);
    }

    private void drawCard(Graphics2D g, DashboardSnapshot snapshot, DashboardWidgetType type,
        Rectangle bounds, boolean visible)
    {
        if (bounds == null || !panelBounds.intersects(bounds))
        {
            return;
        }
        List<String> lines = snapshot.getLines().getOrDefault(type, Collections.emptyList());
        List<FarmPage> farmPages = type == DashboardWidgetType.FARM_RUNS
            ? farmPages(lines, farmPageCapacity(bounds)) : Collections.emptyList();
        if (type == DashboardWidgetType.FARM_RUNS)
        {
            farmPageCount = Math.max(1, farmPages.size());
            farmPage = Math.max(0, Math.min(farmPage, farmPageCount - 1));
        }
        if (type == DashboardWidgetType.GE_MARKET)
        {
            gePageCount = Math.max(1,
                (lines.size() + GE_ITEMS_PER_PAGE - 1) / GE_ITEMS_PER_PAGE);
            gePage = Math.max(0, Math.min(gePage, gePageCount - 1));
        }
        int configuredAlpha = config.dashboardOpacity() * 255 / 100;
        int alpha = editing && !visible ? Math.min(65, configuredAlpha)
            : configuredAlpha;
        Color accent = accent(type);
        g.setPaint(new GradientPaint(bounds.x, bounds.y,
            alpha(theme().cardTop(), alpha), bounds.x, bounds.y + bounds.height,
            alpha(theme().card(), alpha)));
        g.fillRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, 9, 9);
        g.setColor(editing && !visible ? theme().muted() : theme().border());
        g.drawRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, 9, 9);

        g.setColor(accent);
        g.fillRoundRect(bounds.x, bounds.y, 5, bounds.height, 9, 9);

        BufferedImage icon = type == DashboardWidgetType.SLAYER
            ? slayerImageService.getImage() : null;
        if (icon == null)
        {
            icon = itemManager.getImage(widgetIconId(type));
        }
        g.setColor(new Color(accent.getRed(), accent.getGreen(), accent.getBlue(), 42));
        g.fillOval(bounds.x + 14, bounds.y + 14, 48, 48);
        g.setColor(new Color(accent.getRed(), accent.getGreen(), accent.getBlue(), 125));
        g.drawOval(bounds.x + 14, bounds.y + 14, 48, 48);
        if (icon != null)
        {
            g.drawImage(icon, bounds.x + 18, bounds.y + 18, 40, 40, null);
            g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER,
                editing && !visible ? 0.04f : 0.10f));
            g.drawImage(icon, bounds.x + bounds.width - 92, bounds.y + bounds.height - 88,
                76, 76, null);
            g.setComposite(AlphaComposite.SrcOver);
        }

        g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 13));
        g.setColor(editing && !visible ? theme().muted() : theme().primary());
        String cardTitle = type == DashboardWidgetType.SLAYER
            && slayerImageService.isShowingBoss()
            && slayerImageService.getDisplayName() != null
                ? slayerImageService.getDisplayName() + " Boss Guide" : type.getTitle();
        if (type == DashboardWidgetType.FARM_RUNS && !farmPages.isEmpty())
        {
            cardTitle = "Farm Runs \u00b7 " + farmPages.get(farmPage).title;
        }
        g.drawString(ellipsize(cardTitle, g.getFontMetrics(), bounds.width - 86),
            bounds.x + 72, bounds.y + 31);
        g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 9));
        g.setColor(new Color(accent.getRed(), accent.getGreen(), accent.getBlue(),
            editing && !visible ? 100 : 220));
        String category = category(type);
        if (type == DashboardWidgetType.GE_MARKET && !editing)
        {
            category = "BIGGEST 24H MOVES" + (gePageCount > 1
                ? " · PAGE " + (gePage + 1) + "/" + gePageCount : "");
        }
        if (type == DashboardWidgetType.SLAYER && !editing)
        {
            boolean bossAvailable = slayerImageService.getBossVariantName() != null;
            if (bossAvailable)
            {
                category = slayerImageService.isShowingBoss()
                    ? "BOSS VARIANT · USE TASK BUTTON TO RETURN"
                    : "BOSS AVAILABLE · USE BOSS BUTTON";
            }
            if (slayerView == 0)
            {
                category += " · CARD FOR LOADOUT";
            }
            else if (slayerView == 1)
            {
                category += " · CLICK FOR BEST TO WORST";
            }
            else
            {
                int pages = recommendationPageCount(slayerImageService.getLoadout());
                category += slayerRecommendationPage + 1 < pages
                    ? " · CLICK FOR NEXT PAGE" : " · CLICK FOR GUIDE";
            }
        }
        boolean showBossButton = type == DashboardWidgetType.SLAYER && !editing
            && slayerImageService.getBossVariantName() != null;
        if (showBossButton)
        {
            bossButtonBounds = new Rectangle(bounds.x + bounds.width - 94,
                bounds.y + 43, 80, 23);
        }
        if (type == DashboardWidgetType.SLAYER && !editing)
        {
            int right = showBossButton ? bossButtonBounds.x - 7 : bounds.x + bounds.width - 14;
            wikiButtonBounds = new Rectangle(right - 80, bounds.y + 43, 80, 23);
        }
        int categoryWidth = type == DashboardWidgetType.SLAYER && !editing
            ? Math.max(40, wikiButtonBounds.x - (bounds.x + 72) - 7) : bounds.width - 86;
        g.drawString(ellipsize(category, g.getFontMetrics(), categoryWidth),
            bounds.x + 72, bounds.y + 50);
        if (showBossButton)
        {
            g.setColor(alpha(theme().cardTop(), 235));
            g.fillRoundRect(bossButtonBounds.x, bossButtonBounds.y,
                bossButtonBounds.width, bossButtonBounds.height, 7, 7);
            g.setColor(theme().primary());
            g.drawRoundRect(bossButtonBounds.x, bossButtonBounds.y,
                bossButtonBounds.width, bossButtonBounds.height, 7, 7);
            String label = slayerImageService.isShowingBoss() ? "‹ TASK" : "BOSS ›";
            g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 9));
            FontMetrics buttonMetrics = g.getFontMetrics();
            g.setColor(theme().primary());
            g.drawString(label, bossButtonBounds.x
                    + (bossButtonBounds.width - buttonMetrics.stringWidth(label)) / 2,
                bossButtonBounds.y + 15);
        }
        if (type == DashboardWidgetType.SLAYER && !editing)
        {
            g.setColor(alpha(theme().cardTop(), 215));
            g.fillRoundRect(wikiButtonBounds.x, wikiButtonBounds.y,
                wikiButtonBounds.width, wikiButtonBounds.height, 7, 7);
            g.setColor(theme().border());
            g.drawRoundRect(wikiButtonBounds.x, wikiButtonBounds.y,
                wikiButtonBounds.width, wikiButtonBounds.height, 7, 7);
            String label = "WIKI ↗";
            g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 9));
            FontMetrics wikiMetrics = g.getFontMetrics();
            g.setColor(theme().text());
            g.drawString(label, wikiButtonBounds.x
                    + (wikiButtonBounds.width - wikiMetrics.stringWidth(label)) / 2,
                wikiButtonBounds.y + 15);
        }
        if (editing)
        {
            String state = (visible ? "VISIBLE" : "HIDDEN") + " · "
                + layout.span(type) + " COL";
            g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 10));
            FontMetrics fm = g.getFontMetrics();
            g.setColor(visible ? theme().positive() : theme().muted());
            g.drawString(state, bounds.x + 12, bounds.y + bounds.height - 12);
            g.setColor(alpha(theme().primary(), 185));
            for (int handleY = 0; handleY < 3; handleY++)
            {
                for (int handleX = 0; handleX < 2; handleX++)
                {
                    g.fillOval(bounds.x + bounds.width - 25 + handleX * 7,
                        bounds.y + 20 + handleY * 7, 3, 3);
                }
            }
        }
        g.setColor(new Color(255, 255, 255, 18));
        g.drawLine(bounds.x + 12, bounds.y + 74, bounds.x + bounds.width - 12, bounds.y + 74);

        List<Integer> rowItemIds = snapshot.getItemIds().getOrDefault(type,
            Collections.emptyList());
        if (type == DashboardWidgetType.GE_MARKET)
        {
            int first = gePage * GE_ITEMS_PER_PAGE;
            int end = Math.min(lines.size(), first + GE_ITEMS_PER_PAGE);
            lines = first < end ? new ArrayList<>(lines.subList(first, end))
                : Collections.emptyList();
            int itemEnd = Math.min(rowItemIds.size(), first + GE_ITEMS_PER_PAGE);
            rowItemIds = first < itemEnd
                ? new ArrayList<>(rowItemIds.subList(first, itemEnd))
                : Collections.emptyList();
        }
        if (type == DashboardWidgetType.FARM_RUNS)
        {
            drawFarmPatchLines(g, farmPages, bounds);
            lines = Collections.emptyList();
        }
        else if (type == DashboardWidgetType.SLAYER && slayerView == 1)
        {
            drawSlayerLoadout(g, bounds, slayerImageService.getLoadout());
            lines = Collections.emptyList();
        }
        else if (type == DashboardWidgetType.SLAYER && slayerView == 2)
        {
            drawSlayerRecommendations(g, bounds, slayerImageService.getLoadout());
            lines = Collections.emptyList();
        }
        int lineY = bounds.y + 99;
        int bottom = bounds.y + bounds.height - (editing ? 31 : 13);
        if (type == DashboardWidgetType.BANK_HISTORY)
        {
            bottom -= 77;
        }
        else if (type == DashboardWidgetType.SLAYER)
        {
            bottom = bounds.y + bounds.height - 27;
        }
        else if (type == DashboardWidgetType.GE_MARKET && gePageCount > 1)
        {
            bottom -= 15;
        }
        for (int index = 0; index < lines.size(); index++)
        {
            String line = lines.get(index);
            if (lineY > bottom)
            {
                break;
            }
            boolean headline = index == 0 && (type == DashboardWidgetType.BANK_HISTORY
                || type == DashboardWidgetType.RECENT_LOOT);
            g.setFont(new Font(Font.SANS_SERIF, headline ? Font.BOLD : Font.PLAIN,
                headline ? 16 : 11));
            boolean positive = line.startsWith("+") || line.startsWith("↑")
                || line.contains("ready")
                || line.startsWith("✓");
            boolean negative = line.contains(" -") || line.startsWith("-")
                || line.startsWith("↓");
            g.setColor(positive ? theme().positive() : negative ? theme().negative()
                : headline ? theme().primary() : theme().text());
            int textX = bounds.x + 14;
            if (index < rowItemIds.size() && rowItemIds.get(index) > 0)
            {
                BufferedImage rowIcon = itemManager.getImage(rowItemIds.get(index));
                if (rowIcon != null)
                {
                    g.drawImage(rowIcon, bounds.x + 12, lineY - 15, 20, 18, null);
                    textX += 25;
                }
            }
            if (line.startsWith("○ ") || line.startsWith("✓ "))
            {
                g.setColor(line.startsWith("✓") ? theme().positive() : theme().muted());
                g.fillOval(bounds.x + 14, lineY - 9, 8, 8);
                textX += 16;
                line = line.substring(2);
                g.setColor(line.startsWith("✓") ? theme().positive() : theme().text());
            }
            int textWidth = bounds.width - (textX - bounds.x) - 14;
            int wrappedLineHeight = headline ? 18 : 14;
            int maxWrappedLines = Math.max(1, (bottom - lineY) / wrappedLineHeight + 1);
            List<String> wrapped = wrapText(line, g.getFontMetrics(), textWidth,
                maxWrappedLines);
            for (String wrappedLine : wrapped)
            {
                if (lineY > bottom)
                {
                    break;
                }
                g.drawString(wrappedLine, textX, lineY);
                lineY += wrappedLineHeight;
            }
            lineY += headline ? 7 : type == DashboardWidgetType.SLAYER ? 4 : 7;
        }
        if (type == DashboardWidgetType.GE_MARKET && gePageCount > 1 && !editing)
        {
            String pageHint = "Click for next page";
            g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 9));
            FontMetrics pageMetrics = g.getFontMetrics();
            g.setColor(theme().muted());
            g.drawString(pageHint, bounds.x + bounds.width - 14
                    - pageMetrics.stringWidth(pageHint),
                bounds.y + bounds.height - 13);
        }
        if (type == DashboardWidgetType.BANK_HISTORY)
        {
            drawBankChart(g, snapshot.getBankHistory(), bounds.x + 14,
                bounds.y + bounds.height - 75, bounds.width - 28, 56);
        }
        else if (type == DashboardWidgetType.SLAYER && slayerView == 0)
        {
            drawSlayerProgress(g, lines, bounds);
        }

        if (editing && type == dragTargetWidget && type != draggingWidget)
        {
            g.setStroke(new BasicStroke(3f));
            g.setColor(theme().positive());
            g.drawRoundRect(bounds.x + 2, bounds.y + 2, bounds.width - 4,
                bounds.height - 4, 9, 9);
            String placement = dragTargetAfter ? "PLACE AFTER" : "PLACE BEFORE";
            g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 10));
            FontMetrics placementMetrics = g.getFontMetrics();
            int placementWidth = placementMetrics.stringWidth(placement) + 14;
            int placementY = dragTargetAfter ? bounds.y + bounds.height - 29 : bounds.y + 7;
            g.setColor(alpha(theme().cardTop(), 235));
            g.fillRoundRect(bounds.x + (bounds.width - placementWidth) / 2, placementY,
                placementWidth, 19, 7, 7);
            g.setColor(theme().positive());
            g.drawString(placement, bounds.x + (bounds.width
                - placementMetrics.stringWidth(placement)) / 2, placementY + 13);
        }
        else if (editing && type == draggingWidget)
        {
            g.setColor(alpha(theme().primary(), 60));
            g.fillRoundRect(bounds.x + 2, bounds.y + 2, bounds.width - 4,
                bounds.height - 4, 9, 9);
            g.setStroke(new BasicStroke(2f));
            g.setColor(theme().primary());
            g.drawRoundRect(bounds.x + 2, bounds.y + 2, bounds.width - 4,
                bounds.height - 4, 9, 9);
        }
    }

    private void drawFarmPatchLines(Graphics2D g, List<FarmPage> pages, Rectangle bounds)
    {
        if (pages.isEmpty())
        {
            return;
        }
        List<String> lines = pages.get(farmPage).lines;
        int columns = bounds.width >= 760 ? 3 : bounds.width >= 520 ? 2 : 1;
        int cellHeight = 30;
        int rows = Math.max(1, (bounds.height - 104) / cellHeight);
        int columnWidth = (bounds.width - 28 - (columns - 1) * 14) / columns;

        g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 10));
        for (int index = 0; index < lines.size(); index++)
        {
            int column = index / rows;
            int row = index % rows;
            int x = bounds.x + 14 + column * (columnWidth + 14);
            int y = bounds.y + 94 + row * cellHeight;
            String line = lines.get(index);
            String lower = line.toLowerCase();
            g.setColor(lower.endsWith("done") ? theme().positive()
                : lower.endsWith("diseased") || lower.endsWith("dead")
                    ? theme().negative() : theme().text());
            for (String wrapped : wrapText(line, g.getFontMetrics(), columnWidth, 2))
            {
                g.drawString(wrapped, x, y);
                y += 13;
            }
        }

        if (farmPageCount > 1)
        {
            String page = "Page " + (farmPage + 1) + "/" + farmPageCount
                + " · click for next patch type";
            g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 9));
            FontMetrics metrics = g.getFontMetrics();
            g.setColor(theme().muted());
            g.drawString(page, bounds.x + bounds.width - 14 - metrics.stringWidth(page),
                bounds.y + bounds.height - 13);
        }
    }

    private static int farmPageCapacity(Rectangle bounds)
    {
        int columns = bounds.width >= 760 ? 3 : bounds.width >= 520 ? 2 : 1;
        int rows = Math.max(1, (bounds.height - 104) / 30);
        return Math.max(1, rows * columns);
    }

    static List<FarmPage> farmPages(List<String> lines, int capacity)
    {
        Map<String, List<String>> categories = new LinkedHashMap<>();
        for (String line : lines)
        {
            int separator = line.indexOf('\u00b7');
            String category = separator > 0 ? line.substring(0, separator).trim()
                : "Patch Status";
            String detail = separator > 0 ? line.substring(separator + 1).trim() : line;
            categories.computeIfAbsent(farmCategoryTitle(category), ignored -> new ArrayList<>())
                .add(detail);
        }

        List<FarmPage> pages = new ArrayList<>();
        int pageCapacity = Math.max(1, capacity);
        for (Map.Entry<String, List<String>> entry : categories.entrySet())
        {
            List<String> categoryLines = entry.getValue();
            for (int first = 0; first < categoryLines.size(); first += pageCapacity)
            {
                pages.add(new FarmPage(entry.getKey(), new ArrayList<>(categoryLines.subList(
                    first, Math.min(categoryLines.size(), first + pageCapacity)))));
            }
        }
        return pages;
    }

    private static String farmCategoryTitle(String category)
    {
        switch (category.toLowerCase())
        {
            case "herb": return "Herbs";
            case "tree": return "Trees";
            case "fruit tree": return "Fruit Trees";
            case "flower": return "Flowers";
            case "bush": return "Bushes";
            case "grape": return "Grapes";
            case "allotment": return "Allotments";
            default: return category;
        }
    }

