        g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 11));
        g.setColor(theme().primary());
        g.drawString(ellipsize(loadout.getLabel(), g.getFontMetrics(), width), left,
            bounds.y + 92);

        int columns = Math.max(4, Math.min(8, width / 88));
        int gearRows = Math.min(2, Math.max(1,
            (Math.min(loadout.getGear().size(), columns * 2) + columns - 1) / columns));
        int gearY = bounds.y + 112;
        drawLoadoutLabel(g, "GEAR", left, bounds.y + 106);
        drawLoadoutItems(g, loadout.getGear(), left, gearY, width, columns, 2);

