    private void drawLoadoutItems(Graphics2D g, List<SlayerImageService.Detail> items,
        int x, int y, int width, int columns, int rows)
    {
        int cellWidth = width / columns;
        int count = Math.min(items.size(), columns * rows);
        for (int index = 0; index < count; index++)
        {
            SlayerImageService.Detail item = items.get(index);
            int column = index % columns;
            int row = index / columns;
            int cellX = x + column * cellWidth;
            int cellY = y + row * 44;
            BufferedImage icon = item.getImage();
            if (icon == null && item.getItemId() > 0)
            {
                icon = itemManager.getImage(item.getItemId());
            }
            if (icon != null)
            {
                g.drawImage(icon, cellX + (cellWidth - 28) / 2, cellY, 28, 25, null);
            }
            g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, cellWidth >= 90 ? 10 : 9));
            g.setColor(theme().text());
            FontMetrics metrics = g.getFontMetrics();
            List<String> labels = wrapText(item.getText(), metrics, cellWidth - 6, 2);
            int labelY = cellY + 33;
            for (String label : labels)
            {
                g.drawString(label, cellX + (cellWidth - metrics.stringWidth(label)) / 2,
                    labelY);
                labelY += 10;
            }
        }
    }

