            + (slayerRecommendationPage + 1) + "/" + pages;
        g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 12));
        g.setColor(theme().primary());
        g.drawString(ellipsize(title, g.getFontMetrics(), width), left, bounds.y + 93);

        int first = slayerRecommendationPage * RECOMMENDATION_ROWS_PER_PAGE;
        int end = Math.min(rows.size(), first + RECOMMENDATION_ROWS_PER_PAGE);
        for (int index = first; index < end; index++)
