    private void drawRecommendationRow(Graphics2D g,
        SlayerImageService.RecommendationRow row, int x, int y, int width)
    {
        int slotWidth = width >= 500 ? 70 : 50;
        g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 10));
        g.setColor(theme().muted());
        g.drawString(row.getSlot().toUpperCase(java.util.Locale.ENGLISH), x, y + 27);

        List<SlayerImageService.Detail> items = row.getAlternatives();
        int itemCount = Math.min(5, items.size());
        int choicesWidth = width - slotWidth;
        int cellWidth = Math.max(1, choicesWidth / Math.max(1, itemCount));
        for (int rank = 0; rank < itemCount; rank++)
        {
            SlayerImageService.Detail item = items.get(rank);
            int cellX = x + slotWidth + rank * cellWidth;
            g.setColor(rank == 0 ? alpha(theme().positive(), 28)
                : new Color(255, 255, 255, 10));
            g.fillRoundRect(cellX + 2, y, Math.max(1, cellWidth - 5), 44, 6, 6);
            g.setColor(rank == 0 ? alpha(theme().positive(), 115)
                : new Color(255, 255, 255, 22));
            g.drawRoundRect(cellX + 2, y, Math.max(1, cellWidth - 5), 44, 6, 6);
            BufferedImage icon = item.getImage();
            if (icon == null && item.getItemId() > 0)
            {
                icon = itemManager.getImage(item.getItemId());
            }
            if (icon != null)
            {
                g.drawImage(icon, cellX + (cellWidth - 26) / 2, y + 1, 26, 23, null);
            }
            g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 8));
            g.setColor(rank == 0 ? theme().positive() : theme().muted());
            g.drawString(Integer.toString(rank + 1), cellX + 5, y + 10);
            g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, cellWidth >= 70 ? 10 : 9));
            g.setColor(rank == 0 ? theme().positive() : theme().text());
            FontMetrics metrics = g.getFontMetrics();
            List<String> labels = wrapText(item.getText(), metrics, cellWidth - 7, 2);
            int labelY = y + 31;
            for (String label : labels)
            {
                g.drawString(label, cellX + (cellWidth - metrics.stringWidth(label)) / 2,
                    labelY);
                labelY += 10;
            }
        }
        g.setColor(new Color(255, 255, 255, 12));
        g.drawLine(x, y + 45, x + width, y + 45);
    }

    private static int recommendationPageCount(SlayerImageService.Loadout loadout)
    {
        return Math.max(1, (loadout.getRecommendations().size()
            + RECOMMENDATION_ROWS_PER_PAGE - 1) / RECOMMENDATION_ROWS_PER_PAGE);
    }

    static List<String> wrapText(String value, FontMetrics metrics, int width, int maxLines)
    {
        if (value == null || value.isEmpty() || width <= 0 || maxLines <= 0)
        {
            return Collections.singletonList("");
        }
        List<String> result = new ArrayList<>();
        StringBuilder current = new StringBuilder();
        String[] words = value.trim().split("\\s+");
        int index = 0;
        while (index < words.length && result.size() < maxLines)
        {
            String candidate = current.length() == 0 ? words[index]
                : current + " " + words[index];
            if (metrics.stringWidth(candidate) <= width)
            {
                current.setLength(0);
                current.append(candidate);
                index++;
                continue;
            }
            if (current.length() == 0)
            {
                current.append(ellipsize(words[index], metrics, width));
                index++;
            }
            result.add(current.toString());
            current.setLength(0);
        }
        if (result.size() < maxLines && current.length() > 0)
        {
            result.add(current.toString());
        }
        if (index < words.length && !result.isEmpty())
        {
            String remaining = result.remove(result.size() - 1) + " "
                + String.join(" ", java.util.Arrays.copyOfRange(words, index, words.length));
            result.add(ellipsize(remaining, metrics, width));
        }
        return result.isEmpty() ? Collections.singletonList(ellipsize(value, metrics, width)) : result;
    }

    private void drawSlayerProgress(Graphics2D g, List<String> lines, Rectangle bounds)
    {
        int percent = 0;
        for (String line : lines)
        {
            if (line.endsWith("% complete"))
            {
                try
                {
                    int marker = line.indexOf("% complete");
                    int start = marker;
                    while (start > 0 && Character.isDigit(line.charAt(start - 1)))
                    {
                        start--;
                    }
                    percent = Integer.parseInt(line.substring(start, marker));
                }
                catch (NumberFormatException ignored)
                {
                    percent = 0;
                }
            }
        }
        int x = bounds.x + 14;
        int y = bounds.y + bounds.height - 17;
        int width = bounds.width - 28;
        g.setColor(new Color(255, 255, 255, 22));
        g.fillRoundRect(x, y, width, 8, 8, 8);
        g.setColor(theme().positive());
        g.fillRoundRect(x, y, width * Math.max(0, Math.min(100, percent)) / 100, 8, 8, 8);
    }

