    private void drawBankChart(Graphics2D g, BankHistoryStore.BankHistory history,
        int x, int y, int width, int height)
    {
        List<BankHistoryStore.BankSample> values = history.getSamples();
        if (values.size() < 2 || width < 20 || height < 20)
        {
            return;
        }
        long min = Long.MAX_VALUE;
        long max = Long.MIN_VALUE;
        for (BankHistoryStore.BankSample value : values)
        {
            min = Math.min(min, value.getValue());
            max = Math.max(max, value.getValue());
        }
        if (min == max)
        {
            min--;
            max++;
        }
        Path2D path = new Path2D.Double();
        for (int i = 0; i < values.size(); i++)
        {
            double px = x + i * (width - 1.0) / (values.size() - 1.0);
            double py = y + (max - values.get(i).getValue()) * (height - 1.0) / (max - min);
            if (i == 0)
            {
                path.moveTo(px, py);
            }
            else
            {
                path.lineTo(px, py);
            }
        }
        g.setColor(new Color(255, 255, 255, 12));
        g.fillRoundRect(x, y, width, height, 6, 6);
        g.setColor(values.get(values.size() - 1).getValue() >= values.get(0).getValue()
            ? theme().positive() : theme().negative());
        g.setStroke(new BasicStroke(2f));
        g.draw(path);
    }

