    {
        layout.toggleSpan(type);
        layoutStore.save(layout);
    }

    void beginReorder(DashboardWidgetType moving)
    {
        draggingWidget = moving;
        dragTargetWidget = null;
    }

    void updateReorder(int x, int y)
    {
        DashboardWidgetType target = widgetAt(x, y);
        if (target == draggingWidget)
        {
            target = null;
        }
        dragTargetWidget = target;
        Rectangle bounds = target == null ? null : cardBounds.get(target);
        dragTargetAfter = bounds != null && y >= bounds.y + bounds.height / 2;
    }

    void commitReorder()
    {
        if (draggingWidget != null && dragTargetWidget != null)
        {
            layout.move(draggingWidget, dragTargetWidget, dragTargetAfter);
            layoutStore.save(layout);
        }
        clearReorder();
    }

    void clearReorder()
    {
        draggingWidget = null;
        dragTargetWidget = null;
        dragTargetAfter = false;
    }

    void scroll(int amount)
    {
        scroll = Math.max(0, scroll + amount);
    }

    DashboardWidgetType widgetAt(int x, int y)
    {
        for (Map.Entry<DashboardWidgetType, Rectangle> entry : cardBounds.entrySet())
        {
            if (entry.getValue().contains(x, y))
            {
                return entry.getKey();
            }
        }
        return null;
    }

    void activateWidget(DashboardWidgetType type, int mouseX, int mouseY)
    {
        Rectangle bounds = cardBounds.get(type);
        if (type == DashboardWidgetType.SLAYER && wikiButtonBounds.contains(mouseX, mouseY))
        {
            dataService.openSlayerWiki();
            return;
        }
        if (type == DashboardWidgetType.SLAYER && bossButtonBounds.contains(mouseX, mouseY))
        {
            if (slayerImageService.toggleBossVariant())
            {
                slayerView = 0;
                slayerRecommendationPage = 0;
                dataService.invalidate();
            }
            return;
        }
        if (type == DashboardWidgetType.DAILIES && bounds != null)
        {
            int line = (mouseY - bounds.y - 42) / 17;
            if (line >= 1)
            {
                dataService.toggleDaily(line - 1);
            }
        }
        else if (type == DashboardWidgetType.NEWS && bounds != null)
        {
            int line = (mouseY - bounds.y - 42) / 17;
            if (line >= 0)
            {
                dataService.openNews(line);
            }
        }
        else if (type == DashboardWidgetType.FARM_RUNS)
        {
            farmPage = (farmPage + 1) % Math.max(1, farmPageCount);
        }
        else if (type == DashboardWidgetType.GE_MARKET)
        {
            gePage = (gePage + 1) % Math.max(1, gePageCount);
        }
        else if (type == DashboardWidgetType.SLAYER)
        {
            if (slayerView == 0)
            {
                slayerView = 1;
            }
            else if (slayerView == 1)
            {
                slayerView = 2;
                slayerRecommendationPage = 0;
            }
            else
            {
                int pages = recommendationPageCount(slayerImageService.getLoadout());
                if (++slayerRecommendationPage >= pages)
                {
                    slayerView = 0;
                    slayerRecommendationPage = 0;
                }
            }
        }
    }

    boolean isOpen()
    {
        return open;
    }

    boolean isEditing()
    {
        return editing;
    }

    Rectangle getPanelBounds()
    {
        return new Rectangle(panelBounds);
    }

    Rectangle getCloseBounds()
    {
        return new Rectangle(closeBounds);
    }

    Rectangle getEditBounds()
    {
        return new Rectangle(editBounds);
    }

    private void clearBounds()
    {
        panelBounds = new Rectangle();
        cardBounds.clear();
    }

    private DashboardTheme theme()
    {
        DashboardTheme configured = config.dashboardTheme();
        return configured == null ? DashboardTheme.GIELINOR : configured;
    }

    private static Color alpha(Color color, int alpha)
    {
        return new Color(color.getRed(), color.getGreen(), color.getBlue(), alpha);
    }

    private static String ellipsize(String value, FontMetrics metrics, int width)
    {
        if (metrics.stringWidth(value) <= width)
        {
            return value;
        }
        String suffix = "…";
        int end = value.length();
        while (end > 0 && metrics.stringWidth(value.substring(0, end) + suffix) > width)
        {
            end--;
        }
        return value.substring(0, end) + suffix;
    }
}

