package com.gielinorbriefing;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

@Singleton
class MarketHistoryStore
{
    private static final String KEY = "marketHistory";
    private static final int MAX_POINTS = 144;

    private final ConfigManager configManager;

    @Inject
    MarketHistoryStore(ConfigManager configManager)
    {
        this.configManager = configManager;
    }

    synchronized List<Double> record(double value, Instant timestamp)
    {
        List<Point> points = loadPoints();
        long minute = timestamp.getEpochSecond() / 60;
        if (points.isEmpty() || points.get(points.size() - 1).minute != minute)
        {
            points.add(new Point(minute, value));
        }
        else
        {
            points.set(points.size() - 1, new Point(minute, value));
        }

        if (points.size() > MAX_POINTS)
        {
            points = new ArrayList<>(points.subList(points.size() - MAX_POINTS, points.size()));
        }

        StringBuilder encoded = new StringBuilder();
        for (Point point : points)
        {
            if (encoded.length() > 0)
            {
                encoded.append(',');
            }
            encoded.append(point.minute).append(':')
                .append(String.format(Locale.ROOT, "%.4f", point.value));
        }
        configManager.setConfiguration(GielinorBriefingConfig.GROUP, KEY, encoded.toString());

        List<Double> values = new ArrayList<>();
        for (Point point : points)
        {
            values.add(point.value);
        }
        return Collections.unmodifiableList(values);
    }

    private List<Point> loadPoints()
    {
        String encoded = configManager.getConfiguration(GielinorBriefingConfig.GROUP, KEY);
        List<Point> points = new ArrayList<>();
        if (encoded == null || encoded.isEmpty())
        {
            return points;
        }

        for (String entry : encoded.split(","))
        {
            String[] parts = entry.split(":", 2);
            if (parts.length != 2)
            {
                continue;
            }
            try
            {
                points.add(new Point(Long.parseLong(parts[0]), Double.parseDouble(parts[1])));
            }
            catch (NumberFormatException ignored)
            {
                // Retain valid history points if one cache entry is malformed.
            }
        }
        return points;
    }

    private static final class Point
    {
        private final long minute;
        private final double value;

        private Point(long minute, double value)
        {
            this.minute = minute;
            this.value = value;
        }
    }
}

package com.gielinorbriefing;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

@Singleton
class DashboardLayoutStore
{
    static final String ORDER_KEY = "widgetOrder";
    static final String VISIBLE_KEY = "visibleWidgets";
    static final String SPANS_KEY = "widgetSpans";
    private static final String VERSION_KEY = "layoutVersion";
    private static final String VERSION = "6";

    private final ConfigManager configManager;

    @Inject
    DashboardLayoutStore(ConfigManager configManager)
    {
        this.configManager = configManager;
    }

    synchronized Layout load()
    {
        List<DashboardWidgetType> order = parseOrder(configManager.getConfiguration(
            GielinorBriefingConfig.GROUP, ORDER_KEY));
        Set<DashboardWidgetType> visible = parseVisible(configManager.getConfiguration(
            GielinorBriefingConfig.GROUP, VISIBLE_KEY));
        boolean hasVisibilitySettings = false;
        for (DashboardWidgetType type : DashboardWidgetType.values())
        {
            String configured = configManager.getConfiguration(GielinorBriefingConfig.GROUP,
                visibilityKey(type));
            if (configured != null)
            {
                hasVisibilitySettings = true;
                if (Boolean.parseBoolean(configured))
                {
                    visible.add(type);
                }
                else
                {
                    visible.remove(type);
                }
            }
        }
        String version = configManager.getConfiguration(GielinorBriefingConfig.GROUP, VERSION_KEY);
        Map<DashboardWidgetType, Integer> spans = parseSpans(VERSION.equals(version)
            ? configManager.getConfiguration(GielinorBriefingConfig.GROUP, SPANS_KEY) : null);
        if (!VERSION.equals(version))
        {
            configManager.setConfiguration(GielinorBriefingConfig.GROUP, VERSION_KEY, VERSION);
        }
        if (!hasVisibilitySettings)
        {
            // One-time migration from the original Edit-mode-only visibility setting.
            saveVisibilitySettings(visible);
        }
        return new Layout(order, visible, spans);
    }

    synchronized void save(Layout layout)
    {
        configManager.setConfiguration(GielinorBriefingConfig.GROUP, ORDER_KEY,
            layout.order.stream().map(Enum::name).collect(Collectors.joining(",")));
        String visible = layout.visible.stream().map(Enum::name).collect(Collectors.joining(","));
        configManager.setConfiguration(GielinorBriefingConfig.GROUP, VISIBLE_KEY,
            visible.isEmpty() ? "NONE" : visible);
        saveVisibilitySettings(layout.visible);
        configManager.setConfiguration(GielinorBriefingConfig.GROUP, SPANS_KEY,
            layout.order.stream().map(type -> type.name() + ":" + layout.span(type))
                .collect(Collectors.joining(",")));
        configManager.setConfiguration(GielinorBriefingConfig.GROUP, VERSION_KEY, VERSION);
    }

    private void saveVisibilitySettings(Set<DashboardWidgetType> visible)
    {
        for (DashboardWidgetType type : DashboardWidgetType.values())
        {
            configManager.setConfiguration(GielinorBriefingConfig.GROUP, visibilityKey(type),
                visible.contains(type));
        }
    }

    static boolean isVisibilityKey(String key)
    {
        return key != null && key.startsWith("showCard");
    }

    private static String visibilityKey(DashboardWidgetType type)
    {
        switch (type)
        {
            case BANK_HISTORY: return "showCardBankHistory";
            case BANK_MOVERS: return "showCardBankMovers";
            case GE_MARKET: return "showCardGeMarket";
            case GE_OFFERS: return "showCardGeOffers";
            case NEWS: return "showCardNews";
            case SLAYER: return "showCardSlayer";
            case FARM_RUNS: return "showCardFarmRuns";
            case BIRD_HOUSES: return "showCardBirdHouses";
            case XP_GOALS: return "showCardXpGoals";
            case RECENT_LOOT: return "showCardRecentLoot";
            case BOSS_PROGRESS: return "showCardBossProgress";
            case QUEST_DIARY: return "showCardQuestDiary";
            case COLLECTION_CLUES: return "showCardCollectionClues";
            case TIMERS: return "showCardTimers";
            case DAILIES: return "showCardDailies";
            default: throw new IllegalArgumentException("Unknown dashboard card " + type);
        }
    }

    private static List<DashboardWidgetType> parseOrder(String value)
    {
        List<DashboardWidgetType> result = new ArrayList<>();
        if (value != null)
        {
            for (String token : value.split(","))
            {
                try
                {
                    DashboardWidgetType type = DashboardWidgetType.valueOf(token.trim());
                    if (!result.contains(type))
                    {
                        result.add(type);
                    }
                }
                catch (IllegalArgumentException ignored)
                {
                    // Skip values from removed or future widgets.
                }
            }
        }
        for (DashboardWidgetType type : DashboardWidgetType.values())
        {
            if (!result.contains(type))
            {
                result.add(type);
            }
        }
        return result;
    }

    private static Set<DashboardWidgetType> parseVisible(String value)
    {
        if (value == null || value.trim().isEmpty())
        {
            return Arrays.stream(DashboardWidgetType.values())
                .filter(DashboardWidgetType::isDefaultVisible)
                .collect(Collectors.toCollection(() -> EnumSet.noneOf(DashboardWidgetType.class)));
        }
        Set<DashboardWidgetType> result = EnumSet.noneOf(DashboardWidgetType.class);
        for (String token : value.split(","))
        {
            try
            {
                result.add(DashboardWidgetType.valueOf(token.trim()));
            }
            catch (IllegalArgumentException ignored)
            {
                // Skip malformed values.
            }
        }
        return result;
    }

    private static Map<DashboardWidgetType, Integer> parseSpans(String value)
    {
        Map<DashboardWidgetType, Integer> result = new EnumMap<>(DashboardWidgetType.class);
        for (DashboardWidgetType type : DashboardWidgetType.values())
        {
            result.put(type, type.getDefaultSpan());
        }
        if (value != null)
        {
            for (String token : value.split(","))
            {
                String[] parts = token.split(":", 2);
                try
                {
                    result.put(DashboardWidgetType.valueOf(parts[0]),
                        Math.max(1, Math.min(3, Integer.parseInt(parts[1]))));
                }
                catch (RuntimeException ignored)
                {
                    // Retain the default span.
                }
            }
        }
        return result;
    }

    static final class Layout
    {
        private final List<DashboardWidgetType> order;
        private final Set<DashboardWidgetType> visible;
        private final Map<DashboardWidgetType, Integer> spans;

        Layout(List<DashboardWidgetType> order, Set<DashboardWidgetType> visible,
            Map<DashboardWidgetType, Integer> spans)
        {
            this.order = new ArrayList<>(order);
            this.visible = visible.isEmpty() ? EnumSet.noneOf(DashboardWidgetType.class)
                : EnumSet.copyOf(visible);
            this.spans = new EnumMap<>(spans);
        }

        List<DashboardWidgetType> getOrder()
        {
            return Collections.unmodifiableList(order);
        }

        boolean isVisible(DashboardWidgetType type)
        {
            return visible.contains(type);
        }

        int span(DashboardWidgetType type)
        {
            return spans.getOrDefault(type, type.getDefaultSpan());
        }

        void toggle(DashboardWidgetType type)
        {
            if (!visible.remove(type))
            {
                visible.add(type);
            }
        }

        void toggleSpan(DashboardWidgetType type)
        {
            spans.put(type, span(type) % 3 + 1);
        }

        void move(DashboardWidgetType type, DashboardWidgetType target, boolean after)
        {
            if (type == target || !order.remove(type))
            {
                return;
            }
            int index = order.indexOf(target);
            if (after && index >= 0)
            {
                index++;
            }
            order.add(index < 0 ? order.size() : index, type);
        }
    }
}
